/**
 * global-filters.ts - Global filter management (sidebar filters for Overview/Trends).
 */

import {
    D,
    currentPage,
    dateRangeFrom,
    dateRangeTo,
    setDateRange,
    setDateRangeFrom,
    setDateRangeTo,
    setCurrentWeekIdx,
    filterOwner,
    setFilterOwner,
    setFilterCountry,
    setFilterDocType,
    activeTypes,
    setActiveTypes,
} from '../state';
import { getDefaultDateRange } from '../data/week-loader';
import { updateTypeBtnLabel } from './type-filter';

/**
 * Remove legacy week shortcut controls when older generated HTML still has them.
 */
export function repopulateWeekSelector(): void {
    const sel = document.getElementById('weekSelector') as HTMLSelectElement | null;
    document.querySelectorAll('.sb-shortcut-label').forEach(label => label.remove());
    if (sel) sel.remove();
}

function ensureDateRangeInputs(): void {
    if (document.getElementById('dateRangeFrom') && document.getElementById('dateRangeTo')) return;

    const reportingSection = Array.from(document.querySelectorAll('.sb-section'))
        .find(section => section.querySelector('.sb-section-title')?.textContent?.trim() === 'Reporting Period');
    if (!reportingSection) return;

    const wrap = document.createElement('div');
    wrap.className = 'sb-date-range';
    wrap.innerHTML = `
        <label class="sb-date-field">
            <span>From</span>
            <input class="sb-date-input" type="date" id="dateRangeFrom">
        </label>
        <label class="sb-date-field">
            <span>To</span>
            <input class="sb-date-input" type="date" id="dateRangeTo">
        </label>
    `;
    reportingSection.appendChild(wrap);
}

/**
 * Initialize the reporting date range controls from dashboard data.
 */
export function initializeDateRangeControls(): void {
    if (!dateRangeFrom && !dateRangeTo) {
        const range = getDefaultDateRange();
        setDateRange(range.from, range.to);
    }

    ensureDateRangeInputs();
    const fromInput = document.getElementById('dateRangeFrom') as HTMLInputElement | null;
    const toInput = document.getElementById('dateRangeTo') as HTMLInputElement | null;
    if (fromInput) fromInput.value = dateRangeFrom;
    if (toInput) toInput.value = dateRangeTo;
}

/**
 * Populate all filter dropdowns (team members, countries, document types).
 * Called once on init.
 */
export function populateFilters(): void {
    repopulateWeekSelector();
    initializeDateRangeControls();

    // Populate team members
    const ow = document.getElementById('filterOwner') as HTMLSelectElement | null;
    if (ow) {
        D.team_members.forEach(m => {
            const o = document.createElement('option');
            o.value = m;
            o.textContent = m;
            ow.appendChild(o);
        });
    }

    // Populate countries from pre-computed metadata
    const cf = document.getElementById('filterCountry') as HTMLSelectElement | null;
    if (cf) {
        (D.all_countries || []).forEach(c => {
            const o = document.createElement('option');
            o.value = c;
            o.textContent = c;
            cf.appendChild(o);
        });
    }

    // Populate doc types from pre-computed metadata
    const dt = document.getElementById('filterDocType') as HTMLSelectElement | null;
    if (dt) {
        (D.all_doc_types || []).sort().forEach(code => {
            const o = document.createElement('option');
            o.value = code;
            o.textContent = `${code}  ${D.doc_type_labels[code] || code}`;
            dt.appendChild(o);
        });
    }
}

/**
 * Refresh current page after filter change.
 * Dynamically imports page modules to avoid circular dependencies.
 */
async function refreshCurrentPage(): Promise<void> {
    try {
        if (currentPage === 'overview') {
            const { loadWeek } = await import('../pages/overview');
            await loadWeek();
        } else if (currentPage === 'trends') {
            const { renderTrends } = await import('../charts/trend-charts');
            await renderTrends();
        } else if (currentPage === 'detail') {
            const { setDetailFilterDateFrom, setDetailFilterDateTo, setDetailPage } = await import('./detail-filters');
            const { renderDetailTable } = await import('../pages/detail');
            setDetailFilterDateFrom(dateRangeFrom);
            setDetailFilterDateTo(dateRangeTo);
            setDetailPage(1);
            await renderDetailTable();
        }
    } catch (err) {
        console.error('[Filters] Error refreshing current page:', err);
    }
}

/**
 * Bind event listeners to filter controls.
 */
export function bindFilters(): void {
    const fromInput = document.getElementById('dateRangeFrom');
    if (fromInput) {
        fromInput.addEventListener('change', (e) => {
            setDateRangeFrom((e.target as HTMLInputElement).value);
            refreshCurrentPage();
        });
    }

    const toInput = document.getElementById('dateRangeTo');
    if (toInput) {
        toInput.addEventListener('change', (e) => {
            setDateRangeTo((e.target as HTMLInputElement).value);
            refreshCurrentPage();
        });
    }

    const ownerSel = document.getElementById('filterOwner');
    if (ownerSel) {
        ownerSel.addEventListener('change', (e) => {
            setFilterOwner((e.target as HTMLSelectElement).value);
            updateMemberCardStates();
            refreshCurrentPage();
        });
    }

    const countrySel = document.getElementById('filterCountry');
    if (countrySel) {
        countrySel.addEventListener('change', (e) => {
            setFilterCountry((e.target as HTMLSelectElement).value);
            refreshCurrentPage();
        });
    }

    const docTypeSel = document.getElementById('filterDocType');
    if (docTypeSel) {
        docTypeSel.addEventListener('change', (e) => {
            setFilterDocType((e.target as HTMLSelectElement).value);
            refreshCurrentPage();
        });
    }
}

/**
 * Update member card visual states based on filterOwner.
 * Applies 'mc-selected' or 'mc-dimmed' classes.
 */
export function updateMemberCardStates(): void {
    document.querySelectorAll('.member-card[data-member]').forEach((card: Element) => {
        const htmlCard = card as HTMLElement;
        if (filterOwner === 'all') {
            htmlCard.classList.remove('mc-selected', 'mc-dimmed');
        } else if (htmlCard.dataset.member === filterOwner) {
            htmlCard.classList.add('mc-selected');
            htmlCard.classList.remove('mc-dimmed');
        } else {
            htmlCard.classList.remove('mc-selected');
            htmlCard.classList.add('mc-dimmed');
        }
    });
}

/**
 * Handle global type filter change (Manual/CSV/Envoy checkboxes).
 * Preserves current week by week_start match.
 */
export async function onGlobalFilterChange(): Promise<void> {
    try {
        initializeDateRangeControls();
        await refreshCurrentPage();
    } catch (err) {
        console.error('[Filters] Error applying global filter change:', err);
    }
}

/**
 * Reset all filters to default state.
 */
export function resetAllFilters(): void {
    setActiveTypes(new Set(['manual', 'csv', 'envoy']));
    document.querySelectorAll('#msTypeDropdown input[type="checkbox"]').forEach(cb => {
        (cb as HTMLInputElement).checked = true;
    });
    updateTypeBtnLabel();

    setFilterOwner('all');
    setFilterCountry('all');
    setFilterDocType('all');
    const range = getDefaultDateRange();
    setCurrentWeekIdx(0);
    setDateRange(range.from, range.to);

    const ownerSel = document.getElementById('filterOwner') as HTMLSelectElement | null;
    const countrySel = document.getElementById('filterCountry') as HTMLSelectElement | null;
    const docTypeSel = document.getElementById('filterDocType') as HTMLSelectElement | null;
    const fromInput = document.getElementById('dateRangeFrom') as HTMLInputElement | null;
    const toInput = document.getElementById('dateRangeTo') as HTMLInputElement | null;

    if (ownerSel) ownerSel.value = 'all';
    if (countrySel) countrySel.value = 'all';
    if (docTypeSel) docTypeSel.value = 'all';
    if (fromInput) fromInput.value = range.from;
    if (toInput) toInput.value = range.to;

    updateMemberCardStates();

    refreshCurrentPage();
}

// Window bindings for onclick handlers (will be bound in main.ts)
export const windowBindings = {
    selectMember(name: string): void {
        const newOwner = filterOwner === name ? 'all' : name;
        setFilterOwner(newOwner);
        const ownerSel = document.getElementById('filterOwner') as HTMLSelectElement | null;
        if (ownerSel) ownerSel.value = newOwner;
        updateMemberCardStates();
        refreshCurrentPage();
    },

    toggleTypeDropdown(): void {
        document.getElementById('msTypeDropdown')?.classList.toggle('open');
    },

    toggleTypeOption(el: HTMLInputElement): void {
        const val = el.value as 'manual' | 'csv' | 'envoy';
        const newTypes = new Set(activeTypes);
        if (el.checked) {
            newTypes.add(val);
        } else {
            newTypes.delete(val);
        }
        setActiveTypes(newTypes);
        updateTypeBtnLabel();
        onGlobalFilterChange();
    },

    resetAllFilters
};
