/**
 * trend-charts.ts - Rendering for the Trends page (5 charts showing historical performance).
 */

import { D, activeTypes, dateRangeFrom, dateRangeTo, filterOwner, filterCountry, filterDocType, charts } from '../state';
import { fmt, pct } from '../utils/formatters';
import { escapeHtml } from '../utils/sanitize';
import { getCreditNoteCount } from '../utils/data-merge';
import { destroyCharts, getMemberColor } from './chart-utils';
import { Chart } from 'chart.js';
import { getFullWeeksMergedForRange } from '../data/week-loader';
import type { FilteredWeek } from '../types/filtered';
import type { MemberDay, TrendEntry } from '../types/dashboard';

/**
 * Get individual target for a member (falls back to default daily target).
 */
function getTarget(m: string): number {
    return (D.individual_targets?.[m]) || D.daily_target;
}

/**
 * Get active type label string (e.g., "Manual + CSV", "All Types").
 */
export function getTypeLabel(): string {
    const types: string[] = [];
    if (activeTypes.has('manual')) types.push('Manual');
    if (activeTypes.has('csv')) types.push('CSV');
    if (activeTypes.has('envoy')) types.push('Envoy');
    if (types.length === 3) return 'All Types';
    if (types.length === 0) return 'No Types Selected';
    return types.join(' + ');
}

function trendInDateRange(entry: { week_start: string; week_end: string }): boolean {
    const from = dateRangeFrom || dateRangeTo;
    const to = dateRangeTo || dateRangeFrom;
    if (!from && !to) return true;
    const start = from <= to ? from : to;
    const end = from <= to ? to : from;
    return entry.week_end >= start && entry.week_start <= end;
}

/** Week summary for trends page */
interface WeekSummary {
    label: string;
    week_start: string;
    total: number;
    dailyAvg: number;
    days: number;
    memberTotals: Record<string, number>;
    memberTargetPct: Record<string, number>;
    qualityScore: number;
    reversals: number;
    creditNotes: number;
    teamTargetPct: number;
}

function hasDateRange(): boolean {
    return Boolean(dateRangeFrom || dateRangeTo);
}

function getNormalizedRange(): { from: string; to: string } | null {
    const from = dateRangeFrom || dateRangeTo;
    const to = dateRangeTo || dateRangeFrom;
    if (!from && !to) return null;
    return from <= to ? { from, to } : { from: to, to: from };
}

function countSummaryValue(source: MemberDay): { total: number; reversals: number; creditNotes: number } {
    let total = 0;
    if (filterCountry !== 'all') {
        total = source.by_country?.[filterCountry] || 0;
    } else if (filterDocType !== 'all') {
        total = source.by_doc_type?.[filterDocType] || 0;
    } else {
        total = source.total || 0;
    }

    return {
        total,
        reversals: source.reversal_count || 0,
        creditNotes: getCreditNoteCount(source.by_doc_type || {}),
    };
}

function summarizeWeek(
    label: string,
    weekStart: string,
    days: number,
    trendMembers: string[],
    sourcesByMember: (member: string) => MemberDay[]
): WeekSummary {
    const memberTotals: Record<string, number> = {};
    const memberTargetPct: Record<string, number> = {};
    let totalReversals = 0;
    let totalCreditNotes = 0;
    const activeDays = Math.max(days || 1, 1);

    trendMembers.forEach(m => {
        let t = 0;
        sourcesByMember(m).forEach(src => {
            const counted = countSummaryValue(src);
            t += counted.total;
            totalReversals += counted.reversals;
            totalCreditNotes += counted.creditNotes;
        });

        memberTotals[m] = t;
        memberTargetPct[m] = Math.round(t / (getTarget(m) * activeDays) * 100);
    });

    const total = trendMembers.reduce((s, m) => s + memberTotals[m], 0);
    const dailyAvg = Math.round(total / activeDays);
    const qualityScore = total > 0 ? 100 - pct(totalReversals + totalCreditNotes, total) : 100;
    const teamTarget = D.team_members.reduce((s, m) => s + getTarget(m) * activeDays, 0);
    const teamTargetPct = teamTarget > 0 ? Math.round((total / teamTarget) * 100) : 0;

    return {
        label,
        week_start: weekStart,
        total,
        dailyAvg,
        days: activeDays,
        memberTotals,
        memberTargetPct,
        qualityScore,
        reversals: totalReversals,
        creditNotes: totalCreditNotes,
        teamTargetPct
    };
}

function summarizeTrendEntry(
    entry: TrendEntry,
    trendMembers: string[],
    hasM: boolean,
    hasC: boolean,
    hasE: boolean
): WeekSummary {
    return summarizeWeek(
        entry.label,
        entry.week_start,
        entry.working_days || 1,
        trendMembers,
        (member) => {
            const sources: MemberDay[] = [];
            if (hasM && entry.manual?.[member]) sources.push(entry.manual[member]);
            if (hasC && entry.csv?.[member]) sources.push(entry.csv[member]);
            if (hasE && entry.envoy?.[member]) sources.push(entry.envoy[member]);
            return sources;
        }
    );
}

function summarizeFilteredWeek(week: FilteredWeek, trendMembers: string[]): WeekSummary {
    return summarizeWeek(
        week.label,
        week.week_start,
        week.working_days || 1,
        trendMembers,
        (member) => {
            const value = week.weekly_totals?.[member];
            return value ? [value] : [];
        }
    );
}

async function getDailyRangeSummaries(trendMembers: string[]): Promise<WeekSummary[]> {
    if (!hasDateRange()) return [];
    const range = getNormalizedRange();
    if (!range) return [];
    const weeks = await getFullWeeksMergedForRange(range.from, range.to);
    return weeks.map(week => summarizeFilteredWeek(week, trendMembers));
}

/**
 * Render all Trends page charts (5 charts total).
 * Reads from D.trend_data and respects active filters.
 */
export async function renderTrends(): Promise<void> {
    const el = document.getElementById('pageTrends');
    if (!el) return;

    const viewLabel = getTypeLabel();
    const hasM = activeTypes.has('manual');
    const hasC = activeTypes.has('csv');
    const hasE = activeTypes.has('envoy');

    // Filter trend_data entries that have at least one active type
    const trendEntries = [...(D.trend_data || [])].filter(e => {
        if (!trendInDateRange(e)) return false;
        if (hasM && e.manual) return true;
        if (hasC && e.csv) return true;
        if (hasE && e.envoy) return true;
        return false;
    }).reverse(); // chronological order

    // Members to show (respects filterOwner). Includes former members so their
    // historical volume appears in trends; target math below stays active-only.
    const allMembers = [...D.team_members, ...(D.former_members || [])];
    const trendMembers = filterOwner === 'all' ? allMembers : [filterOwner];

    const dailySummaries = await getDailyRangeSummaries(trendMembers);
    const weekSummaries: WeekSummary[] = dailySummaries.length
        ? dailySummaries
        : trendEntries.map(e => summarizeTrendEntry(e, trendMembers, hasM, hasC, hasE));

    if (weekSummaries.length < 1) {
        el.innerHTML = `<div class="page-header"><div><div class="page-title">Trends  ${escapeHtml(viewLabel)}</div><div class="page-subtitle">Need at least 1 week of data for trends</div></div></div>`;
        return;
    }

    // KPI values for header
    const latestSummary = weekSummaries[weekSummaries.length - 1];
    const latestTotal = latestSummary.total;
    const latestAvg = latestSummary.dailyAvg;
    const latestTargetPct = latestSummary.teamTargetPct;
    const latestQuality = latestSummary.qualityScore;

    const tAchCls = latestTargetPct >= 100 ? 'i-green' : latestTargetPct >= 50 ? 'i-amber' : 'i-red';
    const tQualCls = latestQuality >= 95 ? 'i-green' : latestQuality >= 90 ? 'i-amber' : 'i-red';

    // Render page HTML
    el.innerHTML = `
    <div class="page-header fade-in">
      <div><div class="page-title">Trends  ${escapeHtml(viewLabel)}</div><div class="page-subtitle">Performance over time  ${weekSummaries.length} week(s) of data</div></div>
    </div>
    <div class="trend-kpi-row">
      <div class="kpi-card fade-in d1"><div class="kpi-icon i-teal"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg></div><div><div class="kpi-label">Latest Week Total</div><div class="kpi-value">${fmt(latestTotal)}</div></div></div>
      <div class="kpi-card fade-in d2"><div class="kpi-icon i-green"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20V10"/><path d="M18 20V4"/><path d="M6 20v-4"/></svg></div><div><div class="kpi-label">Daily Avg (Latest)</div><div class="kpi-value">${fmt(latestAvg)}</div></div></div>
      <div class="kpi-card fade-in d3"><div class="kpi-icon ${tAchCls}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg></div><div><div class="kpi-label">Team Target (Latest)</div><div class="kpi-value">${latestTargetPct}<span style="font-size:.8rem">%</span></div></div></div>
      <div class="kpi-card fade-in d4"><div class="kpi-icon ${tQualCls}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"/><path d="m9 12 2 2 4-4"/></svg></div><div><div class="kpi-label">Quality (Latest)</div><div class="kpi-value">${latestQuality}<span style="font-size:.8rem">%</span></div></div></div>
    </div>
    <div class="chart-card full fade-in d4" style="margin-bottom:1rem"><div class="section-title">Weekly Team Volume Trend</div><div class="chart-wrap" style="height:300px"><canvas id="cTrendWeekly"></canvas></div></div>
    <div class="chart-card full fade-in d5" style="margin-bottom:1rem"><div class="section-title">Member Comparison Over Weeks</div><div class="chart-wrap" style="height:340px"><canvas id="cTrendMembers"></canvas></div></div>
    <div class="chart-card full fade-in d5" style="margin-bottom:1rem"><div class="section-title">Target Achievement by Member (%)</div><div class="chart-wrap" style="height:340px"><canvas id="cTrendTarget"></canvas></div></div>
    <div class="charts-row" style="margin-bottom:1rem">
      <div class="chart-card fade-in d6"><div class="section-title">Daily Average Trend</div><div class="chart-wrap" style="height:260px"><canvas id="cTrendDailyAvg"></canvas></div></div>
      <div class="chart-card fade-in d7"><div class="section-title">Quality Score Trend</div><div class="chart-wrap" style="height:260px"><canvas id="cTrendQuality"></canvas></div></div>
    </div>
  `;

    // Destroy all charts before re-rendering (prevents memory leak)
    destroyCharts();

    renderWeeklyVolumeTrend(weekSummaries);
    renderMemberComparisonTrend(weekSummaries, trendMembers);
    renderDailyAvgTrend(weekSummaries, trendMembers);
    renderTargetAchievementTrend(weekSummaries, trendMembers);
    renderQualityScoreTrend(weekSummaries);
}

/** Chart 1: Weekly volume trend (bar chart) */
function renderWeeklyVolumeTrend(weekSummaries: WeekSummary[]): void {
    const ctxW = document.getElementById('cTrendWeekly') as HTMLCanvasElement | null;
    if (!ctxW) return;

    charts.trendWeekly = new Chart(ctxW, {
        type: 'bar',
        data: {
            labels: weekSummaries.map(w => w.label),
            datasets: [{
                label: 'Total Invoices',
                data: weekSummaries.map(w => w.total),
                backgroundColor: '#0ea5e966',
                borderColor: '#0ea5e9',
                borderWidth: 2,
                borderRadius: 6,
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { top: 28 } },
            plugins: {
                legend: { display: false },
                tooltip: { backgroundColor: '#1a2340', bodyFont: { family: "'JetBrains Mono'" } }
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { font: { family: "'DM Sans'", size: 11 }, color: '#8896b3' }
                },
                y: {
                    ticks: { font: { family: "'JetBrains Mono'", size: 10 } },
                    grid: { color: 'rgba(255,255,255,.04)' }
                }
            }
        },
        plugins: [{
            id: 'trendBarLabels',
            afterDatasetsDraw(chart: Chart) {
                const ctx = chart.ctx;
                const meta = chart.getDatasetMeta(0);
                const isL = document.body.classList.contains('light');
                meta.data.forEach((bar: { x: number; y: number }, i: number) => {
                    const val = chart.data.datasets[0].data[i] as number;
                    ctx.save();
                    ctx.fillStyle = isL ? '#1e293b' : '#e8ecf4';
                    ctx.font = "700 12px 'JetBrains Mono'";
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'bottom';
                    ctx.fillText(fmt(val), bar.x, bar.y - 6);
                    ctx.restore();
                });
            }
        }]
    });
}

/** Chart 2: Member comparison lines */
function renderMemberComparisonTrend(weekSummaries: WeekSummary[], trendMembers: string[]): void {
    const ctxM = document.getElementById('cTrendMembers') as HTMLCanvasElement | null;
    if (!ctxM) return;

    charts.trendMembers = new Chart(ctxM, {
        type: 'line',
        data: {
            labels: weekSummaries.map(w => w.label),
            datasets: trendMembers.map((m) => {
                const ci = [...D.team_members, ...(D.former_members || [])].indexOf(m);
                return {
                    label: m,
                    data: weekSummaries.map(w => w.memberTotals[m]),
                    borderColor: getMemberColor(ci),
                    backgroundColor: getMemberColor(ci) + '22',
                    tension: 0.3,
                    pointRadius: 5,
                    pointHoverRadius: 7,
                    borderWidth: 2.5,
                    fill: false,
                };
            })
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
                legend: {
                    position: 'bottom',
                    labels: { font: { size: 11 }, padding: 16 }
                },
                tooltip: {
                    backgroundColor: '#1a2340',
                    bodyFont: { family: "'JetBrains Mono'", size: 11 }
                }
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { font: { family: "'DM Sans'", size: 11 }, color: '#8896b3' }
                },
                y: {
                    ticks: { font: { family: "'JetBrains Mono'", size: 10 } },
                    grid: { color: 'rgba(255,255,255,.04)' }
                }
            }
        }
    });
}

/** Chart 3: Daily average trend */
function renderDailyAvgTrend(weekSummaries: WeekSummary[], _trendMembers: string[]): void {
    const ctxA = document.getElementById('cTrendDailyAvg') as HTMLCanvasElement | null;
    if (!ctxA) return;

    charts.trendDailyAvg = new Chart(ctxA, {
        type: 'line',
        data: {
            labels: weekSummaries.map(w => w.label),
            datasets: [{
                label: 'Team Daily Average',
                data: weekSummaries.map(w => w.dailyAvg),
                borderColor: '#34d399',
                backgroundColor: 'rgba(52,211,153,.1)',
                tension: 0.3,
                pointRadius: 6,
                pointHoverRadius: 8,
                borderWidth: 2.5,
                fill: true,
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false },
                tooltip: {
                    backgroundColor: '#1a2340',
                    bodyFont: { family: "'JetBrains Mono'" }
                }
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { font: { family: "'DM Sans'", size: 11 }, color: '#8896b3' }
                },
                y: {
                    ticks: { font: { family: "'JetBrains Mono'", size: 10 } },
                    grid: { color: 'rgba(255,255,255,.04)' }
                }
            }
        },
        plugins: [
            {
                id: 'avgLabels',
                afterDatasetsDraw(chart: Chart) {
                    const ctx = chart.ctx;
                    const meta = chart.getDatasetMeta(0);
                    meta.data.forEach((pt: { x: number; y: number }, i: number) => {
                        const val = chart.data.datasets[0].data[i] as number;
                        ctx.save();
                        ctx.fillStyle = '#34d399';
                        ctx.font = "600 12px 'JetBrains Mono'";
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'bottom';
                        ctx.fillText(fmt(val), pt.x, pt.y - 8);
                        ctx.restore();
                    });
                }
            },
            {
                id: 'targetAvgLine',
                afterDraw(chart: Chart) {
                    const members = filterOwner === 'all' ? D.team_members : [filterOwner];
                    const teamTarget = members.reduce((s, m) => s + getTarget(m), 0);
                    const yS = chart.scales.y;
                    const ty = yS.getPixelForValue(teamTarget);
                    if (ty < yS.top || ty > yS.bottom) return;

                    const ctx = chart.ctx;
                    ctx.save();
                    ctx.beginPath();
                    ctx.setLineDash([5, 4]);
                    ctx.strokeStyle = '#ef4444';
                    ctx.lineWidth = 1.5;
                    ctx.moveTo(chart.chartArea.left, ty);
                    ctx.lineTo(chart.chartArea.right, ty);
                    ctx.stroke();
                    ctx.fillStyle = '#ef4444';
                    ctx.font = "600 10px 'JetBrains Mono'";
                    ctx.textAlign = 'right';
                    ctx.fillText(`Target: ${teamTarget}/day`, chart.chartArea.right, ty - 6);
                    ctx.restore();
                }
            }
        ]
    });
}

/** Chart 4: Target achievement by member (grouped bar) */
function renderTargetAchievementTrend(weekSummaries: WeekSummary[], trendMembers: string[]): void {
    const ctxT = document.getElementById('cTrendTarget') as HTMLCanvasElement | null;
    if (!ctxT) return;

    // Target achievement is active-only -- former members have no target.
    const activeMembers = trendMembers.filter(m => !(D.former_members || []).includes(m));

    charts.trendTarget = new Chart(ctxT, {
        type: 'bar',
        data: {
            labels: weekSummaries.map(w => w.label),
            datasets: activeMembers.map((m) => {
                const ci = D.team_members.indexOf(m);
                return {
                    label: m,
                    data: weekSummaries.map(w => w.memberTargetPct[m]),
                    backgroundColor: getMemberColor(ci) + '88',
                    borderColor: getMemberColor(ci),
                    borderWidth: 1.5,
                    borderRadius: 3,
                };
            })
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { top: 20 } },
            plugins: {
                legend: {
                    position: 'bottom',
                    labels: { font: { size: 11 }, padding: 16 }
                },
                tooltip: {
                    backgroundColor: '#1a2340',
                    bodyFont: { family: "'JetBrains Mono'", size: 11 },
                    callbacks: {
                        label: (c: { dataset: { label?: string }; raw: unknown }) => `  ${c.dataset.label}: ${c.raw}%`
                    }
                }
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { font: { family: "'DM Sans'", size: 11 }, color: '#8896b3' }
                },
                y: {
                    ticks: {
                        font: { family: "'JetBrains Mono'", size: 10 },
                        callback: (v: number | string) => v + '%'
                    },
                    grid: { color: 'rgba(255,255,255,.04)' }
                }
            }
        },
        plugins: [
            {
                id: 'targetBarLabels',
                afterDatasetsDraw(chart: Chart) {
                    const ctx = chart.ctx;
                    const isL = document.body.classList.contains('light');
                    chart.data.datasets.forEach((ds: { data: number[] }, di: number) => {
                        const meta = chart.getDatasetMeta(di);
                        meta.data.forEach((bar: { x: number; y: number }, i: number) => {
                            const val = ds.data[i] as number;
                            if (!val) return;
                            ctx.save();
                            ctx.fillStyle = isL ? '#1e293b' : '#e8ecf4';
                            ctx.font = "600 9px 'JetBrains Mono'";
                            ctx.textAlign = 'center';
                            ctx.textBaseline = 'bottom';
                            ctx.fillText(val + '%', bar.x, bar.y - 3);
                            ctx.restore();
                        });
                    });
                }
            },
            {
                id: 'targetLine100',
                afterDraw(chart: Chart) {
                    const yS = chart.scales.y;
                    const ty = yS.getPixelForValue(100);
                    if (ty < yS.top || ty > yS.bottom) return;

                    const ctx = chart.ctx;
                    ctx.save();
                    ctx.beginPath();
                    ctx.setLineDash([5, 4]);
                    ctx.strokeStyle = '#ef4444';
                    ctx.lineWidth = 1.5;
                    ctx.moveTo(chart.chartArea.left, ty);
                    ctx.lineTo(chart.chartArea.right, ty);
                    ctx.stroke();
                    ctx.fillStyle = '#ef4444';
                    ctx.font = "600 10px 'JetBrains Mono'";
                    ctx.textAlign = 'right';
                    ctx.fillText('100% Target', chart.chartArea.right, ty - 6);
                    ctx.restore();
                }
            }
        ]
    });
}

/** Chart 5: Quality score trend */
function renderQualityScoreTrend(weekSummaries: WeekSummary[]): void {
    const ctxQ = document.getElementById('cTrendQuality') as HTMLCanvasElement | null;
    if (!ctxQ) return;

    charts.trendQuality = new Chart(ctxQ, {
        type: 'line',
        data: {
            labels: weekSummaries.map(w => w.label),
            datasets: [{
                label: 'Quality Score',
                data: weekSummaries.map(w => w.qualityScore),
                borderColor: '#a78bfa',
                backgroundColor: 'rgba(167,139,250,.1)',
                tension: 0.3,
                pointRadius: 6,
                pointHoverRadius: 8,
                borderWidth: 2.5,
                fill: true,
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false },
                tooltip: {
                    backgroundColor: '#1a2340',
                    bodyFont: { family: "'JetBrains Mono'" },
                    callbacks: {
                        label: (c: { raw: unknown }) => `  Quality: ${c.raw}%`
                    }
                }
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { font: { family: "'DM Sans'", size: 11 }, color: '#8896b3' }
                },
                y: {
                    min: 80,
                    max: 100,
                    ticks: {
                        font: { family: "'JetBrains Mono'", size: 10 },
                        callback: (v: number | string) => v + '%'
                    },
                    grid: { color: 'rgba(255,255,255,.04)' }
                }
            }
        },
        plugins: [
            {
                id: 'qualityLabels',
                afterDatasetsDraw(chart: Chart) {
                    const ctx = chart.ctx;
                    const meta = chart.getDatasetMeta(0);
                    meta.data.forEach((pt: { x: number; y: number }, i: number) => {
                        const val = chart.data.datasets[0].data[i] as number;
                        ctx.save();
                        ctx.fillStyle = '#a78bfa';
                        ctx.font = "600 12px 'JetBrains Mono'";
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'bottom';
                        ctx.fillText(val + '%', pt.x, pt.y - 8);
                        ctx.restore();
                    });
                }
            },
            {
                id: 'qualityThreshold',
                afterDraw(chart: Chart) {
                    const yS = chart.scales.y;
                    const ty = yS.getPixelForValue(95);
                    if (ty < yS.top || ty > yS.bottom) return;

                    const ctx = chart.ctx;
                    ctx.save();
                    ctx.beginPath();
                    ctx.setLineDash([5, 4]);
                    ctx.strokeStyle = '#10b981';
                    ctx.lineWidth = 1;
                    ctx.moveTo(chart.chartArea.left, ty);
                    ctx.lineTo(chart.chartArea.right, ty);
                    ctx.stroke();
                    ctx.fillStyle = '#10b981';
                    ctx.font = "500 9px 'JetBrains Mono'";
                    ctx.textAlign = 'right';
                    ctx.fillText('95% threshold', chart.chartArea.right, ty - 4);
                    ctx.restore();
                }
            }
        ]
    });
}
