/**
 * type-filter.ts - Global type filter (Manual/CSV/Envoy) management.
 */

import { activeTypes } from '../state';

/**
 * Get human-readable label for currently active types.
 * @returns Label string (e.g., "All", "Manual + CSV", "None")
 */
export function getTypeLabel(): string {
    const hasM = activeTypes.has('manual');
    const hasC = activeTypes.has('csv');
    const hasE = activeTypes.has('envoy');

    if (hasM && hasC && hasE) return 'All';

    const parts: string[] = [];
    if (hasM) parts.push('Manual');
    if (hasC) parts.push('CSV');
    if (hasE) parts.push('Envoy');

    return parts.length > 0 ? parts.join(' + ') : 'None';
}

/**
 * Update type button label in UI to reflect current selection.
 */
export function updateTypeBtnLabel(): void {
    const btn = document.getElementById('btnGlobalType');
    if (!btn) return;
    btn.textContent = getTypeLabel();
}
