/**
 * SLA Email Tracker page - TL operational view for shared mailbox backlog.
 */

import { D } from '../state';
import type {
    SlaActionLog,
    SlaDailyHistory,
    SlaOpenEmail,
    SlaOwnerSummary,
    SlaSupplierSummary,
    SlaTrackerKpis,
    SlaTrackerData,
    SlaWeeklyOwnerSummary,
} from '../types/dashboard';
import { escapeHtml } from '../utils/sanitize';

type CsvColumn<T> = {
    header: string;
    value: (row: T) => string | number | boolean | null | undefined;
};

type SlaFilter = {
    owner?: string;
    supplier?: string;
};

type SlaTableState = {
    search: string;
    pageSize: number;
    page: number;
};

let activeFilter: SlaFilter = {};
const tableStates: Record<string, SlaTableState> = {};
const SLA_PAGE_SIZES = [10, 20, 50];

function el(id: string): HTMLElement | null {
    return document.getElementById(id);
}

function text(value: string | number | boolean | null | undefined): string {
    if (value === null || value === undefined || value === '') {
        return '-';
    }
    return String(value);
}

function boolText(value: boolean): string {
    return value ? 'Yes' : 'No';
}

function html(value: string | number | boolean | null | undefined): string {
    return escapeHtml(text(value));
}

function numberText(value: number | null | undefined, decimals = 0): string {
    if (value === null || value === undefined || Number.isNaN(value)) {
        return '-';
    }
    return value.toLocaleString('en-GB', {
        maximumFractionDigits: decimals,
        minimumFractionDigits: decimals,
    });
}

function statusBadge(status: string | undefined): string {
    const value = text(status);
    return `<span class="calendar-type">${escapeHtml(value)}</span>`;
}

function hasTrackerData(tracker: SlaTrackerData | undefined): tracker is SlaTrackerData {
    if (!tracker) {
        return false;
    }
    return Boolean(
        tracker.kpis
        || tracker.owner_summary?.length
        || tracker.weekly_owner_summary?.length
        || tracker.daily_history?.length
        || tracker.open_emails?.length
        || tracker.action_log?.length
        || tracker.supplier_summary?.length,
    );
}

function formatDateTime(value: string | undefined): string {
    if (!value) {
        return '-';
    }
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) {
        return value;
    }
    return parsed.toLocaleString('en-GB', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
    });
}

function renderKpi(label: string, value: string, tone: 'teal' | 'green' | 'amber' | 'red' = 'teal', hint = ''): string {
    return `
      <div class="kpi-card" data-kpi-label="${escapeHtml(label)}">
        <div class="kpi-icon i-${tone}">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19V5"/><path d="M4 19h16"/><path d="M8 16v-5"/><path d="M12 16V8"/><path d="M16 16v-3"/></svg>
        </div>
        <div>
          <div class="kpi-label">${escapeHtml(label)}</div>
          <div class="kpi-value">${escapeHtml(value)}</div>
          ${hint ? `<div class="kpi-hint">${escapeHtml(hint)}</div>` : ''}
        </div>
      </div>
    `;
}

function emptyRow(colspan: number, label: string): string {
    return `<tr><td colspan="${colspan}" class="calendar-empty">${escapeHtml(label)}</td></tr>`;
}

function normalize(value: string | null | undefined): string {
    return (value || '').trim().toLocaleLowerCase('en-GB');
}

function tableState(tableId: string): SlaTableState {
    tableStates[tableId] ||= { search: '', pageSize: 10, page: 1 };
    return tableStates[tableId];
}

function clearTableStates(): void {
    Object.keys(tableStates).forEach(key => {
        delete tableStates[key];
    });
}

function rowOwner(row: { owner_display?: string; folder_path?: string }): string {
    return normalize(row.owner_display || row.folder_path?.split(/[\\/]/).filter(Boolean).pop());
}

function matchesFilter(
    row: { owner_display?: string; folder_path?: string; supplier_key?: string },
    filter: SlaFilter,
): boolean {
    if (filter.owner && rowOwner(row) !== normalize(filter.owner)) {
        return false;
    }
    if (filter.supplier && normalize(row.supplier_key) !== normalize(filter.supplier)) {
        return false;
    }
    return true;
}

function applyFilter<T extends { owner_display?: string; folder_path?: string; supplier_key?: string }>(
    rows: T[] = [],
    filter: SlaFilter = activeFilter,
): T[] {
    if (!filter.owner && !filter.supplier) {
        return rows;
    }
    return rows.filter(row => matchesFilter(row, filter));
}

function createOwnerSummary(data: SlaTrackerData): SlaOwnerSummary[] {
    if (data.owner_summary?.length) {
        return data.owner_summary;
    }

    const rows = new Map<string, SlaOwnerSummary>();
    for (const row of data.weekly_owner_summary || []) {
        const owner = text(row.owner_display);
        rows.set(owner, {
            owner_display: owner,
            open_count: row.open_count || 0,
            received_this_week: 0,
            actioned_this_week: 0,
            weekly_gap: 0,
        });
    }
    for (const row of data.open_emails || []) {
        const owner = text(row.owner_display);
        const current = rows.get(owner) || {
            owner_display: owner,
            open_count: 0,
            received_this_week: 0,
            actioned_this_week: 0,
            weekly_gap: 0,
        };
        current.open_count = (current.open_count || 0) + 1;
        rows.set(owner, current);
    }
    return Array.from(rows.values()).sort((left, right) => (right.open_count || 0) - (left.open_count || 0));
}

function signedNumber(value: number | null | undefined): string {
    const numeric = Number(value || 0);
    if (numeric > 0) {
        return `+${numberText(numeric)}`;
    }
    return numberText(numeric);
}

function netTone(value: number | null | undefined): 'teal' | 'green' | 'amber' | 'red' {
    const numeric = Number(value || 0);
    if (numeric < 0) {
        return 'green';
    }
    if (numeric > 100) {
        return 'red';
    }
    if (numeric > 0) {
        return 'amber';
    }
    return 'teal';
}

function latestWeeklyRows(rows: SlaWeeklyOwnerSummary[] = []): SlaWeeklyOwnerSummary[] {
    const latest = rows
        .map(row => row.week_start || '')
        .filter(Boolean)
        .sort()
        .pop();
    if (!latest) {
        return [];
    }
    return rows
        .filter(row => row.week_start === latest)
        .sort((left, right) => Math.abs(Number(right.net_change || 0)) - Math.abs(Number(left.net_change || 0)));
}

function ownerFilteredKpis(kpis: SlaTrackerData['kpis'], ownerSummary: SlaOwnerSummary[]): SlaTrackerKpis {
    if (!activeFilter.owner) {
        return kpis || {};
    }
    const owner = ownerSummary.find(row => normalize(row.owner_display) === normalize(activeFilter.owner));
    if (!owner) {
        return {
            ...(kpis || {}),
            open_emails: 0,
            weekly_received: 0,
            weekly_actioned: 0,
            weekly_gap: 0,
            people_needed: 0,
            avg_resolution_days: 0,
            avg_weekly_actioned_per_owner: 0,
        };
    }
    return {
        ...(kpis || {}),
        open_emails: owner.open_count || 0,
        weekly_received: owner.received_this_week || 0,
        weekly_actioned: owner.actioned_this_week || 0,
        weekly_gap: owner.weekly_gap || 0,
        people_needed: owner.people_needed || 0,
        avg_resolution_days: owner.avg_resolution_days || 0,
        avg_weekly_actioned_per_owner: owner.avg_weekly_actioned || 0,
    };
}

function renderSingleMetricBars(
    title: string,
    description: string,
    rows: SlaOwnerSummary[],
    valueField: keyof Pick<SlaOwnerSummary, 'open_count'>,
): string {
    if (!rows.length) {
        return `
          <section class="calendar-panel sla-chart-card">
            <div class="section-title">${escapeHtml(title)}</div>
            <div class="calendar-empty">No owner rows found</div>
          </section>
        `;
    }

    const maxValue = Math.max(1, ...rows.map(row => Number(row[valueField] || 0)));
    return `
      <section class="calendar-panel sla-chart-card">
        <div class="section-title">${escapeHtml(title)}</div>
        <div class="calendar-status">${escapeHtml(description)}</div>
        <div class="sla-bars" role="list">
          ${rows.map(row => {
              const owner = text(row.owner_display);
              const value = Number(row[valueField] || 0);
              const width = Math.max(4, Math.round((value / maxValue) * 100));
              const active = normalize(activeFilter.owner) === normalize(owner);
              return `
                <button class="sla-bar-button${active ? ' active' : ''}" type="button" data-sla-owner-filter="${escapeHtml(owner)}" aria-pressed="${active}">
                  <span class="sla-bar-label">${escapeHtml(owner)}</span>
                  <span class="sla-bar-track"><span class="sla-bar-fill fill-open" style="width:${width}%"></span></span>
                  <span class="sla-bar-value">${numberText(value)}</span>
                </button>
              `;
          }).join('')}
        </div>
      </section>
    `;
}

function renderOwnerMovementBars(rows: SlaWeeklyOwnerSummary[]): string {
    if (!rows.length) {
        return `
          <section class="calendar-panel sla-chart-card">
            <div class="section-title">Week Net Change by Owner</div>
            <div class="calendar-empty">No owner rows found</div>
          </section>
        `;
    }

    const maxValue = Math.max(1, ...rows.map(row => Math.abs(Number(row.net_change || 0))));

    return `
      <section class="calendar-panel sla-chart-card">
        <div class="section-title">Week Net Change by Owner</div>
        <div class="calendar-status">Negative is backlog reduction; positive means the owner's open queue increased during the Local Fixture Store week.</div>
        <div class="sla-bar-legend" aria-hidden="true">
          <span><i class="legend-actioned"></i>Reduced</span>
          <span><i class="legend-gap"></i>Increased</span>
        </div>
        <div class="sla-bars" role="list">
          ${rows.map(row => {
              const owner = text(row.owner_display);
              const netChange = Number(row.net_change || 0);
              const active = normalize(activeFilter.owner) === normalize(owner);
              const fillClass = netChange <= 0 ? 'fill-actioned' : 'fill-gap';
              return `
                <button class="sla-bar-button${active ? ' active' : ''}" type="button" data-sla-owner-filter="${escapeHtml(owner)}" aria-pressed="${active}">
                  <span class="sla-bar-label">${escapeHtml(owner)}</span>
                  <span class="sla-bar-track"><span class="sla-bar-fill ${fillClass}" style="width:${Math.max(4, Math.round((Math.abs(netChange) / maxValue) * 100))}%"></span></span>
                  <span class="sla-bar-value">${signedNumber(netChange)}</span>
                </button>
              `;
          }).join('')}
        </div>
      </section>
    `;
}

function renderSupplierBacklogBars(rows: SlaSupplierSummary[] = []): string {
    const topRows = [...rows].sort((left, right) => (right.open_count || 0) - (left.open_count || 0)).slice(0, 8);
    if (!topRows.length) {
        return '';
    }
    const maxValue = Math.max(1, ...topRows.map(row => Number(row.open_count || 0)));
    return `
      <section class="calendar-panel sla-chart-card full">
        <div class="section-title">Top Suppliers by Open Backlog</div>
        <div class="calendar-status">Highlights suppliers creating the largest unresolved queue. Click a supplier to filter the email detail tables.</div>
        <div class="sla-bars compact" role="list">
          ${topRows.map(row => {
              const supplier = text(row.supplier_key);
              const owner = text(row.owner_display);
              const value = Number(row.open_count || 0);
              const active = normalize(activeFilter.supplier) === normalize(supplier);
              return `
                <button class="sla-bar-button${active ? ' active' : ''}" type="button" data-sla-supplier-filter="${escapeHtml(supplier)}" aria-pressed="${active}">
                  <span class="sla-bar-label">${escapeHtml(supplier)}  ${escapeHtml(owner)}</span>
                  <span class="sla-bar-track"><span class="sla-bar-fill fill-supplier" style="width:${Math.max(4, Math.round((value / maxValue) * 100))}%"></span></span>
                  <span class="sla-bar-value">${numberText(value)}</span>
                </button>
              `;
          }).join('')}
        </div>
      </section>
    `;
}

function renderActiveFilter(): string {
    if (!activeFilter.owner && !activeFilter.supplier) {
        return '';
    }
    const filterText = activeFilter.owner
        ? `Owner: ${activeFilter.owner}`
        : `Supplier: ${activeFilter.supplier}`;
    return `
      <div class="sla-filter-strip">
        <span>${escapeHtml(filterText)}</span>
        <button class="btn-print sla-export-btn" type="button" data-sla-clear-filter>Clear</button>
      </div>
    `;
}

function renderOwnerFilter(rows: SlaOwnerSummary[]): string {
    const options = rows
        .map(row => row.owner_display || '')
        .filter(Boolean)
        .map(owner => `<option value="${escapeHtml(owner)}"${normalize(owner) === normalize(activeFilter.owner) ? ' selected' : ''}>${escapeHtml(owner)}</option>`)
        .join('');
    return `
      <section class="calendar-panel sla-filter-panel">
        <label class="sla-owner-filter">
          <span>Owner</span>
          <select data-sla-owner-select>
            <option value="">All owners</option>
            ${options}
          </select>
        </label>
        <button class="btn-print sla-export-btn" type="button" data-sla-clear-filter>Clear</button>
        <div class="calendar-status">${activeFilter.owner ? `Tables filtered to ${escapeHtml(activeFilter.owner)}` : 'Tables showing all owners'}</div>
      </section>
    `;
}

