function stringifyForSearch(value: unknown): string {
    if (value === null || value === undefined) {
        return '';
    }
    if (Array.isArray(value)) {
        return value.map(item => stringifyForSearch(item)).join(' ');
    }
    if (typeof value === 'object') {
        return Object.values(value as Record<string, unknown>).map(item => stringifyForSearch(item)).join(' ');
    }
    return String(value);
}

function filterTableRows<T>(rows: T[], search: string): T[] {
    const query = normalize(search);
    if (!query) {
        return rows;
    }
    return rows.filter(row => normalize(stringifyForSearch(row)).includes(query));
}

function renderTable<T>(
    tableId: string,
    title: string,
    description: string,
    button: string,
    headers: string[],
    rows: T[],
    renderRows: (rows: T[]) => string,
    emptyColspan: number,
): string {
    const state = tableState(tableId);
    const searchedRows = filterTableRows(rows, state.search);
    const totalPages = Math.max(1, Math.ceil(searchedRows.length / state.pageSize));
    state.page = Math.min(Math.max(1, state.page), totalPages);
    const startIndex = (state.page - 1) * state.pageSize;
    const pageRows = searchedRows.slice(startIndex, startIndex + state.pageSize);
    const visibleStart = searchedRows.length ? startIndex + 1 : 0;
    const visibleEnd = Math.min(startIndex + state.pageSize, searchedRows.length);
    const rowsHtml = pageRows.length
        ? renderRows(pageRows)
        : emptyRow(emptyColspan, state.search ? 'No rows match this table filter' : 'No rows found');

    return `
      <section class="calendar-panel sla-table-panel">
        <div class="sla-section-head">
          <div>
            <div class="section-title">${escapeHtml(title)}</div>
            <div class="calendar-status">${escapeHtml(description)}</div>
          </div>
          <button class="btn-print sla-export-btn" onclick="${button}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="M7 10l5 5 5-5"/><path d="M12 15V3"/></svg>
            CSV
          </button>
        </div>
        <div class="sla-table-tools">
          <label class="sla-table-search">
            <span>Filter</span>
            <input type="search" value="${escapeHtml(state.search)}" placeholder="Search this table" data-sla-table-search="${escapeHtml(tableId)}">
          </label>
          <label class="sla-table-size">
            <span>Show</span>
            <select data-sla-page-size="${escapeHtml(tableId)}">
              ${SLA_PAGE_SIZES.map(size => `<option value="${size}"${state.pageSize === size ? ' selected' : ''}>${size}</option>`).join('')}
            </select>
          </label>
        </div>
        <div class="calendar-table-wrap">
          <table class="calendar-table" data-sla-table="${escapeHtml(tableId)}">
            <thead><tr>${headers.map(header => `<th>${escapeHtml(header)}</th>`).join('')}</tr></thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>
        <div class="sla-table-footer">
          <span>${numberText(visibleStart)}-${numberText(visibleEnd)} of ${numberText(searchedRows.length)}</span>
          <div class="sla-pagination">
            <button type="button" data-sla-page-prev="${escapeHtml(tableId)}"${state.page <= 1 ? ' disabled' : ''}>Prev</button>
            <span>Page ${numberText(state.page)} of ${numberText(totalPages)}</span>
            <button type="button" data-sla-page-next="${escapeHtml(tableId)}"${state.page >= totalPages ? ' disabled' : ''}>Next</button>
          </div>
        </div>
      </section>
    `;
}

function csvValue(value: string | number | boolean | null | undefined): string {
    if (value === null || value === undefined) {
        return '';
    }
    const normalized = typeof value === 'boolean' ? boolText(value) : String(value);
    if (/[",\r\n]/.test(normalized)) {
        return `"${normalized.replace(/"/g, '""')}"`;
    }
    return normalized;
}

function exportCsv<T>(filename: string, rows: T[], columns: CsvColumn<T>[]): void {
    const csv = [
        columns.map(column => csvValue(column.header)).join(','),
        ...rows.map(row => columns.map(column => csvValue(column.value(row))).join(',')),
    ].join('\n') + '\n';
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
}

function tracker(): SlaTrackerData | undefined {
    return D.sla_tracker;
}

export async function renderSlaEmailTracker(): Promise<void> {
    const page = el('pageSlaEmailTracker');
    if (!page) {
        return;
    }

    const data = tracker();
    if (!hasTrackerData(data)) {
        page.innerHTML = `
          <div class="page-header">
            <div>
              <h1 class="page-title">SLA Email Tracker</h1>
              <p class="page-subtitle">No SLA tracker data found. Run the dashboard export after the Local Fixture Store list snapshot is available.</p>
            </div>
          </div>
          <section class="calendar-panel">
            <div class="calendar-empty">No SLA tracker data found</div>
          </section>
        `;
        return;
    }

    const rawKpis = data.kpis || {};
    const ownerSummary = createOwnerSummary(data);
    const kpis = ownerFilteredKpis(rawKpis, ownerSummary);
    const currentWeekOwnerRows = latestWeeklyRows(data.weekly_owner_summary || []);
    const weeklyRows = applyFilter(data.weekly_owner_summary || []);
    const dailyRows = applyFilter(data.daily_history || []);
    const openEmailRows = applyFilter(data.open_emails || []);
    const actionRows = applyFilter(data.action_log || []);
    const supplierRows = applyFilter(data.supplier_summary || []);

    page.innerHTML = `
      <div class="page-header">
        <div>
          <h1 class="page-title">SLA Email Tracker</h1>
          <p class="page-subtitle">Source updated ${escapeHtml(formatDateTime(data.source_updated_at))}  Generated ${escapeHtml(formatDateTime(data.generated_at))}</p>
        </div>
      </div>

      <div class="kpi-row">
        ${renderKpi('Open Backlog', numberText(kpis.open_emails), 'teal', 'Current open emails')}
        ${renderKpi('New This Week', numberText(kpis.weekly_received), 'green', 'Received in Local Fixture Store week')}
        ${renderKpi('Actioned Week', numberText(kpis.weekly_actioned), 'green', 'Moved from monitored folders')}
        ${renderKpi('Flow Gap', signedNumber(kpis.weekly_gap), netTone(kpis.weekly_gap), 'New minus actioned')}
        ${renderKpi('Avg Resolve', `${numberText(kpis.avg_resolution_days, 1)}d`, 'amber', 'Received to actioned')}
        ${renderKpi('Extra People', numberText(kpis.people_needed, 0), 'teal', 'To close weekly flow gap')}
      </div>

      ${renderOwnerFilter(ownerSummary)}

      <div class="sla-chart-grid">
        ${renderSingleMetricBars(
            'Backlog by Owner',
            'Current open queue by owner. Click a person to drill into the supporting tables.',
            ownerSummary,
            'open_count',
        )}
        ${renderOwnerMovementBars(currentWeekOwnerRows)}
        ${renderSupplierBacklogBars(data.supplier_summary)}
      </div>

      ${renderActiveFilter()}

      <section class="calendar-panel">
        <div class="section-title">Capacity</div>
        <div class="calendar-status">
          Current week is taken from the Local Fixture Store Weekly Owner Summary. Flow Gap = New This Week minus Actioned Week.
          Extra People = positive Flow Gap divided by this week&apos;s average actioned volume per person.
        </div>
        <div class="calendar-status">
          Current week: ${escapeHtml(text(kpis.current_week_start))} to ${escapeHtml(text(kpis.current_week_end))} 
          Avg weekly actioned/person: ${escapeHtml(numberText(kpis.avg_weekly_actioned_per_owner, 1))}
        </div>
      </section>

      ${renderTable(
          'weekly-owner',
          'Weekly Owner View',
          'Backlog movement by owner: start-of-week email count compared with the latest Local Fixture Store folder summary.',
          'exportSlaWeeklyOwnerCSV()',
          ['Week Start', 'Week End', 'Owner', 'Folders', 'Start', 'Latest', 'Net', 'Unread', 'Last Snapshot', 'Status'],
          weeklyRows,
          renderWeeklyRows,
          10,
      )}

      ${renderTable(
          'daily-history',
          'Daily History',
          'End-of-day Local Fixture Store folder snapshots. Net Change is the movement since the previous run for that folder.',
          'exportSlaDailyHistoryCSV()',
          ['Snapshot', 'Folder', 'Open', 'Unread', 'Net Change'],
          dailyRows,
          renderDailyRows,
          5,
      )}

      ${renderTable(
          'open-emails',
          'Open Email Detail',
          'Currently open emails still sitting in monitored folders. Age and SLA are calculated from the received timestamp.',
          'exportSlaOpenEmailsCSV()',
          ['Owner', 'Folder', 'Sender', 'Sender Email', 'Subject', 'Received', 'Age', 'SLA', 'Supplier'],
          openEmailRows,
          renderOpenEmailRows,
          9,
      )}

      ${renderTable(
          'action-log',
          'Action Log',
          'Emails detected as actioned because they left the monitored folder. Actioned time is the audit detection time.',
          'exportSlaActionLogCSV()',
          ['Owner', 'Folder', 'Sender', 'Sender Email', 'Subject', 'Received', 'Actioned', 'Days', 'Action', 'Supplier'],
          actionRows,
          renderActionRows,
          10,
      )}

      ${renderTable(
          'supplier-summary',
          'Supplier Summary',
          'Groups emails by supplier key and owner, usually sender domain first. Use it to find which suppliers drive each owner backlog and weekly flow.',
          'exportSlaSupplierSummaryCSV()',
          ['Supplier Key', 'Owner', 'Open', 'Received Week', 'Actioned Week'],
          supplierRows,
          renderSupplierRows,
          5,
      )}
    `;

    bindSlaFilters(page);
}

function setOwnerFilter(owner: string): void {
    activeFilter = normalize(activeFilter.owner) === normalize(owner) ? {} : { owner };
    void renderSlaEmailTracker();
}

function setSupplierFilter(supplier: string): void {
    activeFilter = normalize(activeFilter.supplier) === normalize(supplier) ? {} : { supplier };
    void renderSlaEmailTracker();
}

function resetSlaFilters(): void {
    activeFilter = {};
    clearTableStates();
}

function bindSlaFilters(page: HTMLElement): void {
    page.querySelectorAll<HTMLSelectElement>('[data-sla-owner-select]').forEach(select => {
        select.addEventListener('change', () => {
            activeFilter = select.value ? { owner: select.value } : {};
            void renderSlaEmailTracker();
        });
    });
    page.querySelectorAll<HTMLButtonElement>('[data-sla-owner-filter]').forEach(button => {
        button.addEventListener('click', () => setOwnerFilter(button.dataset.slaOwnerFilter || ''));
    });
    page.querySelectorAll<HTMLButtonElement>('[data-sla-supplier-filter]').forEach(button => {
        button.addEventListener('click', () => setSupplierFilter(button.dataset.slaSupplierFilter || ''));
    });
    page.querySelectorAll<HTMLButtonElement>('[data-sla-clear-filter]').forEach(button => {
        button.addEventListener('click', () => {
            activeFilter = {};
            void renderSlaEmailTracker();
        });
    });
    page.querySelectorAll<HTMLInputElement>('[data-sla-table-search]').forEach(input => {
        const tableId = input.dataset.slaTableSearch || '';
        input.addEventListener('input', () => {
            const state = tableState(tableId);
            state.search = input.value;
            state.page = 1;
        });
        input.addEventListener('change', () => {
            void renderSlaEmailTracker();
        });
        input.addEventListener('keydown', event => {
            if (event.key === 'Enter') {
                event.preventDefault();
                void renderSlaEmailTracker();
            }
        });
    });
    page.querySelectorAll<HTMLSelectElement>('[data-sla-page-size]').forEach(select => {
        select.addEventListener('change', () => {
            const state = tableState(select.dataset.slaPageSize || '');
            state.pageSize = Number(select.value) || 10;
            state.page = 1;
            void renderSlaEmailTracker();
        });
    });
    page.querySelectorAll<HTMLButtonElement>('[data-sla-page-prev]').forEach(button => {
        button.addEventListener('click', () => {
            const state = tableState(button.dataset.slaPagePrev || '');
            state.page = Math.max(1, state.page - 1);
            void renderSlaEmailTracker();
        });
    });
    page.querySelectorAll<HTMLButtonElement>('[data-sla-page-next]').forEach(button => {
        button.addEventListener('click', () => {
            const state = tableState(button.dataset.slaPageNext || '');
            state.page += 1;
            void renderSlaEmailTracker();
        });
    });
}

