/**
 * main.ts - Application entry point and initialization.
 */

import { D, setCurrentPage } from './state';
import { populateFilters, bindFilters, windowBindings as globalWindowBindings } from './filters/global-filters';
import { detailWindowBindings } from './filters/detail-filters';
import { detailWindowBindings as detailPageBindings } from './pages/detail';
import { loadWeek } from './pages/overview';
import { renderTrends } from './charts/trend-charts';
import { renderDetailTable } from './pages/detail';
import { calendarWindowBindings, renderCalendar } from './pages/calendar';
import { productionOverridesWindowBindings, renderProductionOverrides } from './pages/production-overrides';
import { renderSlaEmailTracker, slaEmailTrackerWindowBindings } from './pages/sla-email-tracker';
import { toggleTheme } from './theme';
import { destroyCharts, initChartDefaults } from './charts/chart-utils';
import type { DashboardPage } from './state';

/**
 * Initialize the dashboard application.
 * Called automatically when DOM is ready.
 */
async function init(): Promise<void> {
    const overlay = document.getElementById('waitOverlay');
    const status = document.getElementById('waitStatus');
    if (!status) return;

    try {
        // Validate data availability
        const hasManual = D.manual_week_index && D.manual_week_index.length;
        const hasCsv = D.csv_week_index && D.csv_week_index.length;
        const hasEnvoy = D.envoy_week_index && D.envoy_week_index.length;

        if (typeof DASHBOARD_DATA === 'undefined' || (!hasManual && !hasCsv && !hasEnvoy)) {
            status.textContent = 'No data found. Run the Python pipeline first.';
            status.style.color = 'var(--red)';
            return;
        }

        // Initialize Chart.js defaults
        initChartDefaults();

        // Initialize filters
        status.textContent = 'Initializing filters...';
        populateFilters();
        bindFilters();

        // Close multi-select dropdowns on outside click
        document.addEventListener('click', (e) => {
            const target = e.target as HTMLElement;
            ['msType', 'msDtType', 'msDtDocType', 'msBlock'].forEach(id => {
                const ms = document.getElementById(id);
                if (ms && !ms.contains(target)) {
                    ms.querySelector('.ms-dropdown')?.classList.remove('open');
                }
            });
        });

        // Load initial page (Overview)
        status.textContent = 'Loading dashboard...';
        await loadWeek();

        // Hide loading overlay
        setTimeout(() => {
            overlay?.classList.add('hidden');
        }, 300);
    } catch (err) {
        console.error('[Main] Error during initialization:', err);
        status.textContent = 'Failed to load dashboard. Please refresh the page.';
        status.style.color = 'var(--red)';
    }
}

/**
 * Switch between pages (Overview, Trends, Detail, Calendar, SLA Email Tracker, Production Overrides).
 * @param page - Target page name
 */
async function switchPage(page: DashboardPage): Promise<void> {
    try {
        setCurrentPage(page);

        // Clean up previous page's charts to prevent memory leaks
        destroyCharts();

        // Update UI
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.querySelectorAll('.sb-nav-item').forEach(n => n.classList.remove('active'));

        const navItem = document.querySelector(`[data-page="${page}"]`);
        if (navItem) {
            navItem.classList.add('active');
        }

        // Render target page
        if (page === 'overview') {
            const pageEl = document.getElementById('pageOverview');
            if (pageEl) pageEl.classList.add('active');
            await loadWeek();
        } else if (page === 'trends') {
            const pageEl = document.getElementById('pageTrends');
            if (pageEl) pageEl.classList.add('active');
            renderTrends();
        } else if (page === 'detail') {
            const pageEl = document.getElementById('pageDetail');
            if (pageEl) pageEl.classList.add('active');
            await renderDetailTable();
        } else if (page === 'calendar') {
            const pageEl = document.getElementById('pageCalendar');
            if (pageEl) pageEl.classList.add('active');
            await renderCalendar();
        } else if (page === 'sla-email-tracker') {
            const pageEl = document.getElementById('pageSlaEmailTracker');
            if (pageEl) pageEl.classList.add('active');
            await renderSlaEmailTracker();
        } else if (page === 'production') {
            const pageEl = document.getElementById('pageProduction');
            if (pageEl) pageEl.classList.add('active');
            await renderProductionOverrides();
        }
    } catch (err) {
        console.error('[Main] Error switching to page:', page, err);
    }
}

/**
 * Bind all window functions for onclick handlers in HTML.
 * This maintains backward compatibility with inline event handlers.
 */
function bindWindowFunctions(): void {
    // Global navigation
    (window as any).switchPage = switchPage;

    // Theme
    (window as any).toggleTheme = toggleTheme;

    // Global filters
    (window as any).selectMember = globalWindowBindings.selectMember;
    (window as any).toggleTypeDropdown = globalWindowBindings.toggleTypeDropdown;
    (window as any).toggleTypeOption = globalWindowBindings.toggleTypeOption;
    (window as any).resetAllFilters = globalWindowBindings.resetAllFilters;

    // Detail page filters
    (window as any).toggleDtDocTypeDropdown = detailWindowBindings.toggleDtDocTypeDropdown;
    (window as any).toggleDtDocTypeOption = detailWindowBindings.toggleDtDocTypeOption;
    (window as any).clearDtDocTypeFilter = detailWindowBindings.clearDtDocTypeFilter;
    (window as any).toggleBlockDropdown = detailWindowBindings.toggleBlockDropdown;
    (window as any).toggleBlockOption = detailWindowBindings.toggleBlockOption;
    (window as any).clearBlockFilter = detailWindowBindings.clearBlockFilter;
    (window as any).toggleDtTypeDropdown = detailWindowBindings.toggleDtTypeDropdown;
    (window as any).toggleDtTypeOption = detailWindowBindings.toggleDtTypeOption;

    // Detail page actions
    (window as any).sortDetail = detailPageBindings.sortDetail;
    (window as any).goToDetailPage = detailPageBindings.goToDetailPage;
    (window as any).toggleDupFilter = detailPageBindings.toggleDupFilter;
    (window as any).resetDetailFilters = detailPageBindings.resetDetailFilters;
    (window as any).exportDetailCSV = detailPageBindings.exportDetailCSV;
    (window as any).searchDetail = detailPageBindings.searchDetail;
    (window as any).setDateFrom = detailPageBindings.setDateFrom;
    (window as any).setDateTo = detailPageBindings.setDateTo;
    (window as any).filterByMember = detailPageBindings.filterByMember;
    (window as any).setDetailOwner = detailPageBindings.setDetailOwner;
    (window as any).changePerPage = detailPageBindings.changePerPage;

    // Calendar page actions
    (window as any).connectCalendarFolder = calendarWindowBindings.connectCalendarFolder;
    (window as any).saveCalendarAbsence = calendarWindowBindings.saveCalendarAbsence;
    (window as any).deleteCalendarAbsence = calendarWindowBindings.deleteCalendarAbsence;

    // SLA Email Tracker page actions
    (window as any).exportSlaWeeklyOwnerCSV = slaEmailTrackerWindowBindings.exportSlaWeeklyOwnerCSV;
    (window as any).exportSlaDailyHistoryCSV = slaEmailTrackerWindowBindings.exportSlaDailyHistoryCSV;
    (window as any).exportSlaOpenEmailsCSV = slaEmailTrackerWindowBindings.exportSlaOpenEmailsCSV;
    (window as any).exportSlaActionLogCSV = slaEmailTrackerWindowBindings.exportSlaActionLogCSV;
    (window as any).exportSlaSupplierSummaryCSV = slaEmailTrackerWindowBindings.exportSlaSupplierSummaryCSV;

    // Production override page actions
    (window as any).connectProductionOverridesFolder = productionOverridesWindowBindings.connectProductionOverridesFolder;
    (window as any).saveProductionOverride = productionOverridesWindowBindings.saveProductionOverride;
    (window as any).deleteProductionOverride = productionOverridesWindowBindings.deleteProductionOverride;
}

// Auto-initialize when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        bindWindowFunctions();
        init();
    });
} else {
    bindWindowFunctions();
    init();
}
