/** Column labels for table headers */
function colLabel(col: string): string {
    const labels: Record<string, string> = {
        country: 'Country', company_code: 'Co Code', supplier_number: 'Supplier',
        reference: 'Reference', document_number: 'Doc No', amount: 'Amount',
        document_type: 'Type', team_member: 'Owner', entry_date: 'Entry Date',
        document_date: 'Doc Date', payment_block: 'Block',
    };
    return labels[col] || col;
}

/**
 * Apply all active filters to invoice list.
 * @returns Filtered and sorted invoice array
 */
export async function getFilteredInvoices(): Promise<Invoice[]> {
    try {
        let rows = await getInvoices();

        // Text search filter
        if (detailFilterText) {
            const q = detailFilterText.toLowerCase();
            rows = rows.filter(r =>
                (r.reference || '').toLowerCase().includes(q) ||
                (r.document_number || '').toLowerCase().includes(q) ||
                (r.vendor_name || '').toLowerCase().includes(q) ||
                (r.supplier_number || '').toLowerCase().includes(q) ||
                (r.company_code || '').toLowerCase().includes(q) ||
                (r.team_member || '').toLowerCase().includes(q) ||
                (r.payment_block || '').toLowerCase().includes(q) ||
                (r.amount != null ? String(r.amount) : '').toLowerCase().includes(q)
            );
        }

        // Date range filters
        if (detailFilterDateFrom) {
            rows = rows.filter(r => r.entry_date >= detailFilterDateFrom);
        }
        if (detailFilterDateTo) {
            rows = rows.filter(r => r.entry_date <= detailFilterDateTo);
        }

        // Member filter
        if (detailFilterMember !== 'all') {
            rows = rows.filter(r => r.team_member === detailFilterMember);
        }

        // Country filter
        if (detailFilterCountry !== 'all') {
            rows = rows.filter(r => r.country === detailFilterCountry);
        }

        // Type filter (Manual/CSV/Envoy)
        const hasDM = detailActiveTypes.has('manual');
        const hasDC = detailActiveTypes.has('csv');
        const hasDEn = detailActiveTypes.has('envoy');
        if (!(hasDM && hasDC && hasDEn)) {
            rows = rows.filter(r => {
                if (r.is_csv === 0 && hasDM) return true;
                if (r.is_csv === 1 && hasDC) return true;
                if (r.is_csv === 2 && hasDEn) return true;
                return false;
            });
        }

        // Document type filter
        if (detailFilterDocTypes.size > 0) {
            rows = rows.filter(r => detailFilterDocTypes.has(r.document_type));
        }

        // Payment block filter
        if (detailFilterBlocks.size > 0) {
            rows = rows.filter(r => {
                const val = (r.payment_block || '').trim();
                if (detailFilterBlocks.has('__none__')) return !val;
                return detailFilterBlocks.has(val);
            });
        }

        // Duplicates filter  group by reference so pairs appear together
        if (detailFilterDuplicates) {
            const dupSet = getDupIndices(rows);
            rows = rows.filter((_, i) => dupSet.has(i));
        }

        // Sort (when dup filter active, primary sort by reference to keep pairs together)
        const col = detailFilterDuplicates ? 'reference' : detailSort.col;
        const dir = detailFilterDuplicates ? 1 : (detailSort.dir === 'asc' ? 1 : -1);
        rows = [...rows].sort((a, b) => {
            if (col === 'amount') {
                const va = Number(a[col as keyof Invoice]) || 0;
                const vb = Number(b[col as keyof Invoice]) || 0;
                return (va - vb) * dir;
            }
            const va = (a[col as keyof Invoice] as string) || '';
            const vb = (b[col as keyof Invoice] as string) || '';
            if (va < vb) return -1 * dir;
            if (va > vb) return 1 * dir;
            return 0;
        });

        return rows;
    } catch (err) {
        console.error('[Detail] Error filtering invoices:', err);
        return [];
    }
}

/**
 * Build member cards (Overview-style) showing possible duplicates per person.
 * Uses filtered invoices (respects date, type, doc type filters) but ignores member filter.
 * @param filteredInvs - Invoices after applying all filters except member
 * @returns HTML string for the member cards grid
 */
function buildMemberCardsHtml(filteredInvs: Invoice[]): string {
    // Get dup indices for filtered invoices
    const dupSet = getDupIndices(filteredInvs);

    // Count dups per member
    const memberDupCounts: Record<string, number> = {};
    filteredInvs.forEach((r, i) => {
        if (dupSet.has(i)) {
            const m = r.team_member || 'Unknown';
            memberDupCounts[m] = (memberDupCounts[m] || 0) + 1;
        }
    });

    // Only show members who have duplicates > 0
    const membersWithDups = D.team_members.filter((m: string) => (memberDupCounts[m] || 0) > 0);

    if (membersWithDups.length === 0) {
        return `<div class="members-grid fade-in" id="dtMemberCards"></div>`;
    }

    const cardCls = (m: string) => {
        if (detailFilterMember === 'all') return '';
        return detailFilterMember === m ? ' mc-selected' : '';
    };
    const cardStyle = (m: string) => {
        const base = 'padding:1.2rem 1.5rem';
        if (detailFilterMember !== 'all' && detailFilterMember !== m) return `${base};display:none`;
        return base;
    };

    let html = `<div class="members-grid fade-in" id="dtMemberCards" style="grid-template-columns:repeat(auto-fill,minmax(220px,1fr))">`;

    membersWithDups.forEach((m: string) => {
        const i = D.team_members.indexOf(m);
        const dupCount = memberDupCounts[m] || 0;
        const escapedName = m.replace(/'/g, "\\'");
        html += `<div class="member-card fade-in d${i + 1}${cardCls(m)}" data-i="${i}" data-member="${escapeHtml(m)}" onclick="filterByMember('${escapedName}')" style="${cardStyle(m)}">
      <div class="mc-top"><div><div class="mc-name" style="font-size:1rem">${escapeHtml(m)}</div><div class="mc-count" style="color:var(--amber);font-size:1.8rem">${fmt(dupCount)}</div><div class="mc-avg">possible duplicates</div></div></div>
    </div>`;
    });

    html += `</div>`;
    return html;
}

/**
 * Get invoices filtered by everything EXCEPT member filter.
 * Used to calculate per-member dup counts for cards.
 */
async function getBaseFilteredInvoices(): Promise<Invoice[]> {
    try {
        let rows = await getInvoices();

        // Date range filters
        if (detailFilterDateFrom) {
            rows = rows.filter(r => r.entry_date >= detailFilterDateFrom);
        }
        if (detailFilterDateTo) {
            rows = rows.filter(r => r.entry_date <= detailFilterDateTo);
        }

        // Type filter (Manual/CSV/Envoy)
        const hasDM = detailActiveTypes.has('manual');
        const hasDC = detailActiveTypes.has('csv');
        const hasDEn = detailActiveTypes.has('envoy');
        if (!(hasDM && hasDC && hasDEn)) {
            rows = rows.filter(r => {
                if (r.is_csv === 0 && hasDM) return true;
                if (r.is_csv === 1 && hasDC) return true;
                if (r.is_csv === 2 && hasDEn) return true;
                return false;
            });
        }

        // Document type filter
        if (detailFilterDocTypes.size > 0) {
            rows = rows.filter(r => detailFilterDocTypes.has(r.document_type));
        }

        // Payment block filter
        if (detailFilterBlocks.size > 0) {
            rows = rows.filter(r => {
                const val = (r.payment_block || '').trim();
                if (detailFilterBlocks.has('__none__')) return !val;
                return detailFilterBlocks.has(val);
            });
        }

        // Country filter
        if (detailFilterCountry !== 'all') {
            rows = rows.filter(r => r.country === detailFilterCountry);
        }

        return rows;
    } catch (err) {
        console.error('[Detail] Error filtering base invoices:', err);
        return [];
    }
}

