/**
 * Render table rows with pagination (called after filters change).
 */
export async function renderDetailRows(): Promise<void> {
    try {
    const filtered = await getFilteredInvoices();
    const baseFiltered = await getBaseFilteredInvoices();

    // Update KPIs from base-filtered data (respects all filters except member)
    const manualCount = baseFiltered.filter(r => r.is_csv === 0).length;
    const csvCount = baseFiltered.filter(r => r.is_csv === 1).length;
    const envoyCount = baseFiltered.filter(r => r.is_csv === 2).length;
    const allDupSet = getDupIndices(baseFiltered);
    const dupCount = allDupSet.size;

    const kpiManual = document.getElementById('kpiManualVal');
    const kpiCsv = document.getElementById('kpiCsvVal');
    const kpiEnvoy = document.getElementById('kpiEnvoyVal');
    const kpiDup = document.getElementById('kpiDupVal');

    if (kpiManual) kpiManual.textContent = fmt(manualCount);
    if (kpiCsv) kpiCsv.textContent = fmt(csvCount);
    if (kpiEnvoy) kpiEnvoy.textContent = fmt(envoyCount);
    if (kpiDup) kpiDup.textContent = fmt(dupCount);

    // Update member cards (rebuild to reflect filter changes)
    const cardsContainer = document.getElementById('dtMemberCards');
    if (cardsContainer) {
        const newCards = buildMemberCardsHtml(baseFiltered);
        cardsContainer.outerHTML = newCards;
    }

    // Update subtitle
    const subtitle = document.getElementById('dtSubtitle');
    if (subtitle) {
        subtitle.textContent = `Showing ${fmt(filtered.length)} of ${fmt(baseFiltered.length)} invoices`;
    }

    // Pagination
    const totalPages = Math.ceil(filtered.length / detailPerPage);
    const start = (detailPage - 1) * detailPerPage;
    const end = start + detailPerPage;
    const pageRows = filtered.slice(start, end);

    // Sort arrow helper
    const sa = (col: string) => {
        const arrow = detailSort.col === col ? (detailSort.dir === 'asc' ? '' : '') : '';
        const cls = detailSort.col === col ? ' sorted' : '';
        return `<th class="${cls}" onclick="sortDetail('${col}')">${colLabel(col)} <span class="sort-arrow">${arrow}</span></th>`;
    };

    // Detect duplicates for row highlighting (always compute  yellow highlight on dup rows)
    const dupSet = getDupIndices(filtered);

    // Build table HTML
    let tableHtml = `
    <div class="detail-tbl-wrap">
      <table class="detail-tbl">
        <thead>
          <tr>
            ${sa('country')}${sa('company_code')}${sa('supplier_number')}${sa('reference')}${sa('document_number')}${sa('amount')}${sa('document_type')}${sa('team_member')}${sa('entry_date')}${sa('document_date')}${sa('payment_block')}
          </tr>
        </thead>
        <tbody>`;

    pageRows.forEach((r, i) => {
        const globalIdx = start + i;
        const isDup = dupSet.has(globalIdx);
        const rowCls = isDup ? ' class="dup-row"' : '';
        const blockVal = (r.payment_block || '').trim();
        const blockPill = blockVal
            ? `<span class="detail-block-pill has-block">${blockVal}</span>`
            : `<span class="detail-block-pill no-block"></span>`;
        tableHtml += `<tr${rowCls}>
        <td>${r.country || ''}</td>
        <td>${r.company_code || ''}</td>
        <td>${r.supplier_number || ''}</td>
        <td class="col-ref">${r.reference || ''}</td>
        <td class="col-ref">${r.document_number || ''}</td>
        <td>${r.amount != null ? fmt(r.amount) : ''}</td>
        <td>${D.doc_type_labels[r.document_type] || r.document_type}</td>
        <td>${r.team_member || ''}</td>
        <td class="col-date">${r.entry_date || ''}</td>
        <td class="col-date">${r.document_date || ''}</td>
        <td class="col-block">${blockPill}</td>
      </tr>`;
    });

    tableHtml += `</tbody></table></div>`;

    // Pagination controls
    if (totalPages > 1) {
        const maxButtons = 7;
        let startPage = Math.max(1, detailPage - Math.floor(maxButtons / 2));
        const endPage = Math.min(totalPages, startPage + maxButtons - 1);
        if (endPage - startPage < maxButtons - 1) startPage = Math.max(1, endPage - maxButtons + 1);

        tableHtml += `<div class="detail-pagination">`;
        tableHtml += `<span class="pg-info">Page ${detailPage} of ${totalPages} (${fmt(filtered.length)} rows)</span>`;
        tableHtml += `<div class="pg-buttons">`;
        tableHtml += `<button class="pg-btn" onclick="goToDetailPage(1)" ${detailPage <= 1 ? 'disabled' : ''}></button>`;
        tableHtml += `<button class="pg-btn" onclick="goToDetailPage(${detailPage - 1})" ${detailPage <= 1 ? 'disabled' : ''}></button>`;
        for (let p = startPage; p <= endPage; p++) {
            tableHtml += `<button class="pg-btn${p === detailPage ? ' active' : ''}" onclick="goToDetailPage(${p})">${p}</button>`;
        }
        tableHtml += `<button class="pg-btn" onclick="goToDetailPage(${detailPage + 1})" ${detailPage >= totalPages ? 'disabled' : ''}></button>`;
        tableHtml += `<button class="pg-btn" onclick="goToDetailPage(${totalPages})" ${detailPage >= totalPages ? 'disabled' : ''}></button>`;
        tableHtml += `</div></div>`;
    }

    const container = document.getElementById('detailTableContainer');
    if (container) {
        container.innerHTML = tableHtml;
    }
    } catch (err) {
        console.error('[Detail] Error rendering detail rows:', err);
    }
}

/** Debounce timer for text search input */
let _searchTimer: ReturnType<typeof setTimeout> | undefined;

// Window bindings for onclick handlers (will be bound in main.ts)
export const detailWindowBindings = {
    sortDetail(col: string): void {
        if (detailSort.col === col) {
            setDetailSort(col, detailSort.dir === 'asc' ? 'desc' : 'asc');
        } else {
            setDetailSort(col, 'desc');
        }
        setDetailPage(1);
        renderDetailRows();
    },

    goToDetailPage(page: number): void {
        setDetailPage(page);
        renderDetailRows();
    },

    searchDetail(value: string): void {
        clearTimeout(_searchTimer);
        _searchTimer = setTimeout(() => {
            setDetailFilterText(value);
            setDetailPage(1);
            renderDetailRows();
        }, 300);
    },

    setDateFrom(value: string): void {
        setDetailFilterDateFrom(value);
        setDetailPage(1);
        renderDetailRows();
    },

    setDateTo(value: string): void {
        setDetailFilterDateTo(value);
        setDetailPage(1);
        renderDetailRows();
    },

    filterByMember(name: string): void {
        // Toggle: click same member again deselects (like Overview)
        const newMember = detailFilterMember === name ? 'all' : name;
        setDetailFilterMember(newMember);
        const select = document.getElementById('dtOwnerFilter') as HTMLSelectElement | null;
        if (select) select.value = newMember;
        updateDetailMemberNavUI();
        setDetailPage(1);
        renderDetailRows();
    },

    setDetailOwner(value: string): void {
        setDetailFilterMember(value || 'all');
        updateDetailMemberNavUI();
        setDetailPage(1);
        renderDetailRows();
    },

    changePerPage(value: string): void {
        setDetailPerPage(Number(value) || 20);
        setDetailPage(1);
        renderDetailRows();
    },

    toggleDupFilter(): void {
        const newState = !detailFilterDuplicates;
        setDetailFilterDuplicates(newState);
        const btn = document.getElementById('btnDupFilter');
        if (btn) btn.classList.toggle('active', newState);
        setDetailPage(1);
        renderDetailRows();
    },

    resetDetailFilters(): void {
        setDetailFilterText('');
        const range = dateRangeFrom || dateRangeTo
            ? { from: dateRangeFrom, to: dateRangeTo }
            : getDefaultDateRange();
        setDetailFilterDateFrom(range.from);
        setDetailFilterDateTo(range.to);
        setDetailFilterMember('all');
        setDetailFilterCountry('all');
        setDetailActiveTypes(new Set(['manual', 'csv', 'envoy']));
        setDetailFilterDocTypes(new Set());
        setDetailFilterBlocks(new Set());
        setDetailFilterDuplicates(false);
        setDetailPerPage(20);
        const btn = document.getElementById('btnDupFilter');
        if (btn) btn.classList.remove('active');
        // Reset checkboxes
        const checks = document.querySelectorAll('#msDtTypeDropdown input[type="checkbox"]');
        checks.forEach((cb) => { (cb as HTMLInputElement).checked = true; });
        setDetailPage(1);
        renderDetailTable();
    },

    async exportDetailCSV(): Promise<void> {
        try {
            const rows = await getFilteredInvoices();
            const headers = ['Country', 'Company Code', 'Supplier', 'Reference', 'Doc No', 'Amount', 'Type', 'Owner', 'Entry Date', 'Doc Date', 'Block'];
            const csvRows = [headers.join(',')];
            for (const r of rows) {
                csvRows.push([
                    r.country, r.company_code, r.supplier_number, r.reference,
                    r.document_number, r.amount, r.document_type, r.team_member,
                    r.entry_date, r.document_date, r.payment_block || ''
                ].map(v => `"${String(v ?? '').replace(/"/g, '""')}"`).join(','));
            }
            const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'invoice_detail.csv';
            a.click();
            URL.revokeObjectURL(url);
        } catch (err) {
            console.error('[Detail] Error exporting CSV:', err);
        }
    }
};
