/**
 * decompression.ts - Decompression utilities for compressed data blobs.
 */

import { WEEK_CACHE, D, setInvoicesCache } from '../state';
import { LRU_CACHE_LIMIT } from '../config';
import { ensureWeekData } from '../data/chunk-loader';
import type { WeekData, Invoice } from '../types/dashboard';

/**
 * Decompress a base64-encoded deflate blob.
 * Tries native DecompressionStream first, falls back to pako.
 *
 * @param b64 - Base64-encoded deflate data
 * @returns Parsed JSON object
 */
export async function decompressBlob(b64: string): Promise<any> {
    try {
        const bin = atob(b64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) {
            bytes[i] = bin.charCodeAt(i);
        }

        // Try native DecompressionStream (modern browsers)
        if ('DecompressionStream' in window) {
            try {
                const ds = new DecompressionStream('deflate');
                const stream = new Blob([bytes]).stream().pipeThrough(ds);
                const text = await new Response(stream).text();
                return JSON.parse(text);
            } catch (e) {
                // Fall back to pako
            }
        }

        // Fallback to pako library
        if (typeof pako !== 'undefined') {
            const inflated = pako.inflate(bytes, { to: 'string' }) as string;
            return JSON.parse(inflated);
        }

        throw new Error('No decompression available. Use Chrome, Edge, or Firefox.');
    } catch (err) {
        console.error('[Decompression] Error decompressing blob:', err);
        throw err;
    }
}

/**
 * Get decompressed week data from cache or decompress from blob.
 * Implements LRU caching (keeps last 6 weeks).
 *
 * @param key - Week cache key (e.g., "manual_2024-01-05")
 * @returns Decompressed week data or null if not found
 */
export async function getWeekBlob(key: string): Promise<WeekData | null> {
    try {
        if (!key) return null;

        // LRU: move to end if already cached
        if (WEEK_CACHE.has(key)) {
            const v = WEEK_CACHE.get(key)!;
            WEEK_CACHE.delete(key);
            WEEK_CACHE.set(key, v);
            return v;
        }

        // Ensure data is available (loads chunk if needed)
        if (!D.compressed_weeks[key]) {
            const loaded = await ensureWeekData(key);
            if (!loaded) return null;
        }

        // Decompress and cache
        const data = await decompressBlob(D.compressed_weeks[key]);
        WEEK_CACHE.set(key, data);

        // LRU eviction: keep only last N weeks
        while (WEEK_CACHE.size > LRU_CACHE_LIMIT) {
            const oldest = WEEK_CACHE.keys().next().value;
            if (oldest) WEEK_CACHE.delete(oldest);
        }

        return data;
    } catch (err) {
        console.error('[Decompression] Error loading week blob:', key, err);
        return null;
    }
}

/**
 * Get decompressed invoices data (cached globally).
 * @returns Array of all invoices
 */
export async function getInvoices(): Promise<Invoice[]> {
    try {
        const cached = (window as any).INVOICES_CACHE;
        if (cached) return cached;

        const data = await decompressBlob(D.compressed_invoices);
        setInvoicesCache(data);
        (window as any).INVOICES_CACHE = data; // For backward compatibility
        return data;
    } catch (err) {
        console.error('[Decompression] Error loading invoices:', err);
        return [];
    }
}
