/**
 * week-loader.ts - Week data loading and date-range merging based on active filters.
 */

import { D, activeTypes } from '../state';
import { getWeekBlob } from '../utils/decompression';
import { mergeWeekData } from '../utils/data-merge';
import type { AbsenceEntry, MemberDay, WeekIndex } from '../types/dashboard';
import type { FilteredWeek } from '../types/filtered';

type WeekIndexWithAvailableDates = WeekIndex & {
    entry_date_min?: string;
    entry_date_max?: string;
};

function emptyMemberDay(): MemberDay {
    return {
        total: 0,
        by_country: {},
        by_doc_type: {},
        reversal_count: 0,
        credit_note_count: 0,
    };
}

function cloneMemberDay(value: MemberDay | undefined): MemberDay {
    return {
        total: value?.total || 0,
        by_country: { ...(value?.by_country || {}) },
        by_doc_type: { ...(value?.by_doc_type || {}) },
        reversal_count: value?.reversal_count || 0,
        credit_note_count: value?.credit_note_count || 0,
    };
}

function addMemberDay(target: MemberDay, source: MemberDay): void {
    target.total += source.total || 0;
    Object.entries(source.by_country || {}).forEach(([key, value]) => {
        target.by_country[key] = (target.by_country[key] || 0) + value;
    });
    Object.entries(source.by_doc_type || {}).forEach(([key, value]) => {
        target.by_doc_type[key] = (target.by_doc_type[key] || 0) + value;
    });
    target.reversal_count += source.reversal_count || 0;
    target.credit_note_count += source.credit_note_count || 0;
}

function normalizeRange(dateFrom: string, dateTo: string): { from: string; to: string } | null {
    if (!dateFrom && !dateTo) return null;
    const from = dateFrom || dateTo;
    const to = dateTo || dateFrom;
    return from <= to ? { from, to } : { from: to, to: from };
}

function parseIsoDate(value: string): Date | null {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value || '');
    if (!match) return null;
    const parsed = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function formatIsoDate(value: Date): string {
    const year = value.getFullYear();
    const month = String(value.getMonth() + 1).padStart(2, '0');
    const day = String(value.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function addDays(value: string, days: number): string {
    const parsed = parseIsoDate(value);
    if (!parsed) return value;
    parsed.setDate(parsed.getDate() + days);
    return formatIsoDate(parsed);
}

function activeTypesAllowInvoice(row: { is_csv?: number }): boolean {
    if (row.is_csv === 0) return activeTypes.has('manual');
    if (row.is_csv === 1) return activeTypes.has('csv');
    if (row.is_csv === 2) return activeTypes.has('envoy');
    return false;
}

function getLatestInvoiceEntryDate(): string {
    if (!D.compressed_invoices || typeof atob === 'undefined' || typeof pako === 'undefined') return '';

    try {
        const bin = atob(D.compressed_invoices);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) {
            bytes[i] = bin.charCodeAt(i);
        }
        const inflated = pako.inflate(bytes, { to: 'string' }) as string;
        const rows = JSON.parse(inflated);
        if (!Array.isArray(rows)) return '';

        return rows.reduce((latest: string, row: { entry_date?: string; posting_date?: string; is_csv?: number }) => {
            if (!activeTypesAllowInvoice(row)) return latest;
            const date = row.entry_date || row.posting_date || '';
            return /^\d{4}-\d{2}-\d{2}$/.test(date) && date > latest ? date : latest;
        }, '');
    } catch (err) {
        return '';
    }
}

function countWeekdays(from: string, to: string): number {
    let count = 0;
    let cursor = from;
    while (cursor <= to) {
        const parsed = parseIsoDate(cursor);
        if (!parsed) break;
        const day = parsed.getDay();
        if (day !== 0 && day !== 6) count += 1;
        cursor = addDays(cursor, 1);
    }
    return Math.max(count, 1);
}

function absenceDays(entries: AbsenceEntry[] | undefined): number {
    return (entries || []).reduce((sum, entry) => sum + (entry.type === 'Half Day' ? 0.5 : 1), 0);
}

function mergeAbsences(
    a: Record<string, AbsenceEntry[]> | undefined,
    b: Record<string, AbsenceEntry[]> | undefined
): Record<string, AbsenceEntry[]> | undefined {
    const merged: Record<string, AbsenceEntry[]> = {};
    [a, b].forEach(source => {
        Object.entries(source || {}).forEach(([member, entries]) => {
            merged[member] = [...(merged[member] || []), ...entries];
        });
    });
    return Object.keys(merged).length ? merged : undefined;
}

function recomputeWorkingDaysPerMember(
    members: string[],
    workingDays: number,
    absences: Record<string, AbsenceEntry[]> | undefined
): Record<string, number> {
    const result: Record<string, number> = {};
    members.forEach(member => {
        result[member] = Math.max(1, workingDays - absenceDays(absences?.[member]));
    });
    return result;
}

function overlapsRange(week: WeekIndex, from: string, to: string): boolean {
    return week.week_end >= from && week.week_start <= to;
}

function allDashboardMembers(): string[] {
    return [...D.team_members, ...(D.former_members || [])];
}

function filterWeekToRange(week: FilteredWeek, dateFrom: string, dateTo: string): FilteredWeek | null {
    const range = normalizeRange(dateFrom, dateTo);
    if (!range) return week;
    if (!overlapsRange(week, range.from, range.to)) return null;

    const from = week.week_start > range.from ? week.week_start : range.from;
    const to = week.week_end < range.to ? week.week_end : range.to;
    const members = allDashboardMembers();
    const daily: FilteredWeek['daily'] = {};
    const weekly_totals: FilteredWeek['weekly_totals'] = {};

    members.forEach(member => {
        weekly_totals[member] = emptyMemberDay();
    });

    Object.keys(week.daily || {}).sort().forEach(date => {
        if (date < from || date > to) return;
        daily[date] = {};
        members.forEach(member => {
            const row = cloneMemberDay(week.daily[date]?.[member]);
            daily[date][member] = row;
            addMemberDay(weekly_totals[member], row);
        });
    });

    // Production overrides are aggregate corrections. When the selected range
    // is the complete source week, retain the exported weekly totals instead
    // of rebuilding them from detail rows and dropping those corrections.
    const coversWholeWeek = range.from <= week.week_start && range.to >= week.week_end;
    const hasWeeklyAggregates = Object.values(week.weekly_totals || {}).some(row => (
        row.total > 0 || Object.keys(row.by_country || {}).length > 0 || Object.keys(row.by_doc_type || {}).length > 0
    ));
    if (coversWholeWeek && hasWeeklyAggregates) {
        members.forEach(member => {
            weekly_totals[member] = cloneMemberDay(week.weekly_totals[member]);
        });
    }

    const absences: Record<string, AbsenceEntry[]> = {};
    Object.entries(week.absences || {}).forEach(([member, entries]) => {
        const selected = entries.filter(entry => entry.date >= from && entry.date <= to);
        if (selected.length) absences[member] = selected;
    });

    const workingDays = countWeekdays(from, to);
    return {
        ...week,
        week_start: from,
        week_end: to,
        label: from === to ? from : `${from} to ${to}`,
        daily,
        weekly_totals,
        working_days: workingDays,
        working_days_per_member: recomputeWorkingDaysPerMember(members, workingDays, absences),
        absences: Object.keys(absences).length ? absences : undefined,
    };
}

/**
 * Get full week data for a specific type and index entry.
 */
export async function getFullWeek(
    type: 'manual' | 'csv' | 'envoy',
    idx_entry: WeekIndex
): Promise<FilteredWeek | null> {
    try {
        const key = `${type}_${idx_entry.extraction_date}`;
        const blob = await getWeekBlob(key);
        if (!blob) return null;

        return {
            ...idx_entry,
            daily: blob.daily,
            weekly_totals: blob.weekly_totals,
            working_days_per_member: blob.working_days_per_member,
            absences: blob.absences,
        };
    } catch (err) {
        console.error('[WeekLoader] Error loading week data:', type, idx_entry.extraction_date, err);
        return null;
    }
}

/**
 * Get merged week index based on active type filters.
 */
export function getWeekIndex(): WeekIndex[] {
    const hasM = activeTypes.has('manual');
    const hasC = activeTypes.has('csv');
    const hasE = activeTypes.has('envoy');

    const map: Record<string, WeekIndex> = {};
    if (hasM) (D.manual_week_index || []).forEach(w => { if (!map[w.extraction_date]) map[w.extraction_date] = w; });
    if (hasC) (D.csv_week_index || []).forEach(w => { if (!map[w.extraction_date]) map[w.extraction_date] = w; });
    if (hasE) (D.envoy_week_index || []).forEach(w => { if (!map[w.extraction_date]) map[w.extraction_date] = w; });

    return Object.values(map).sort((a, b) => b.week_start.localeCompare(a.week_start));
}

/**
 * Default reporting period: latest 7 calendar days covered by available row dates.
 */
export function getDefaultDateRange(): { from: string; to: string } {
    const latestInvoiceDate = getLatestInvoiceEntryDate();
    if (latestInvoiceDate) {
        return {
            from: addDays(latestInvoiceDate, -6),
            to: latestInvoiceDate,
        };
    }

    const weeks = getWeekIndex() as WeekIndexWithAvailableDates[];
    if (!weeks.length) return { from: '', to: '' };
    const availableEnd = (week: WeekIndexWithAvailableDates) => week.entry_date_max || week.week_end;
    const latest = weeks.reduce((best, week) => (availableEnd(week) > availableEnd(best) ? week : best), weeks[0]);
    const latestEnd = availableEnd(latest);
    return {
        from: addDays(latestEnd, -6),
        to: latestEnd,
    };
}

export function getWeekIndexForRange(from: string, to: string): WeekIndex[] {
    const range = normalizeRange(from, to) || getDefaultDateRange();
    if (!range.from || !range.to) return [];
    return getWeekIndex().filter(week => overlapsRange(week, range.from, range.to));
}

async function getFullWeekMergedForEntry(entry: WeekIndex): Promise<FilteredWeek | null> {
    const ed = entry.extraction_date;
    const promises: Promise<FilteredWeek | null>[] = [];

    const mi = (D.manual_week_index || []).find(w => w.extraction_date === ed);
    const ci = (D.csv_week_index || []).find(w => w.extraction_date === ed);
    const ei = (D.envoy_week_index || []).find(w => w.extraction_date === ed);

    if (activeTypes.has('manual') && mi) promises.push(getFullWeek('manual', mi));
    if (activeTypes.has('csv') && ci) promises.push(getFullWeek('csv', ci));
    if (activeTypes.has('envoy') && ei) promises.push(getFullWeek('envoy', ei));

    const results = (await Promise.all(promises)).filter(Boolean) as FilteredWeek[];
    if (!results.length) return null;

    let merged = results[0];
    for (let i = 1; i < results.length; i++) {
        const mergedAbsences = mergeAbsences(merged.absences, results[i].absences);
        merged = mergeWeekData(merged, results[i]);
        merged.absences = mergedAbsences;
    }

    return merged;
}

/**
 * Get full week data merged across all active types.
 */
export async function getFullWeekMerged(idx: number): Promise<FilteredWeek | null> {
    try {
        const weekIndex = getWeekIndex();
        if (!weekIndex.length || idx >= weekIndex.length) return null;
        return getFullWeekMergedForEntry(weekIndex[Math.min(idx, weekIndex.length - 1)]);
    } catch (err) {
        console.error('[WeekLoader] Error merging week data:', err);
        return null;
    }
}

export async function getFullWeeksMergedForRange(dateFrom: string, dateTo: string): Promise<FilteredWeek[]> {
    const range = normalizeRange(dateFrom, dateTo) || getDefaultDateRange();
    if (!range.from || !range.to) return [];

    const entries = getWeekIndexForRange(range.from, range.to)
        .sort((a, b) => a.week_start.localeCompare(b.week_start));

    const filteredWeeks: FilteredWeek[] = [];
    for (const entry of entries) {
        const week = await getFullWeekMergedForEntry(entry);
        const filtered = week ? filterWeekToRange(week, range.from, range.to) : null;
        if (filtered) filteredWeeks.push(filtered);
    }

    return filteredWeeks;
}

/**
 * Get data merged across active types and all weeks overlapping a date range.
 * Weekly extraction blobs are displayed by daily entry dates inside the range.
 */
export async function getFullWeekMergedForRange(dateFrom: string, dateTo: string): Promise<FilteredWeek | null> {
    try {
        const range = normalizeRange(dateFrom, dateTo) || getDefaultDateRange();
        if (!range.from || !range.to) return null;

        const filteredWeeks = await getFullWeeksMergedForRange(range.from, range.to);
        if (!filteredWeeks.length) return null;

        let merged = filteredWeeks[0];
        for (let i = 1; i < filteredWeeks.length; i++) {
            const mergedAbsences = mergeAbsences(merged.absences, filteredWeeks[i].absences);
            merged = mergeWeekData(merged, filteredWeeks[i]);
            merged.absences = mergedAbsences;
        }

        const members = allDashboardMembers();
        const workingDays = countWeekdays(range.from, range.to);
        return {
            ...merged,
            week_start: range.from,
            week_end: range.to,
            label: range.from === range.to ? range.from : `${range.from} to ${range.to}`,
            extraction_date: filteredWeeks[filteredWeeks.length - 1].extraction_date,
            working_days: workingDays,
            working_days_per_member: recomputeWorkingDaysPerMember(members, workingDays, merged.absences),
        };
    } catch (err) {
        console.error('[WeekLoader] Error merging date range:', err);
        return null;
    }
}
