/**
 * theme.ts - Light/dark theme toggle functionality.
 */

import { currentPage } from './state';

/**
 * Toggle between light and dark themes.
 * Updates body class, theme button label/icon, and re-renders current page to update chart colors.
 */
export function toggleTheme(): void {
    document.body.classList.toggle('light');
    const isLight = document.body.classList.contains('light');

    // Update theme button
    const label = document.getElementById('themeLabel');
    if (label) {
        label.textContent = isLight ? 'Dark Mode' : 'Light Mode';
    }

    const icon = document.getElementById('themeIcon');
    if (icon) {
        if (isLight) {
            // Moon icon (for dark mode option)
            icon.innerHTML = '<path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/>';
        } else {
            // Sun icon (for light mode option)
            icon.innerHTML = '<circle cx="12" cy="12" r="4"/><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/>';
        }
    }

    // Re-render current page to update chart colors
    refreshPageForTheme();
}

/**
 * Refresh current page to apply theme changes to charts.
 */
async function refreshPageForTheme(): Promise<void> {
    try {
        if (currentPage === 'overview') {
            const { loadWeek } = await import('./pages/overview');
            await loadWeek();
        } else if (currentPage === 'trends') {
            const { renderTrends } = await import('./charts/trend-charts');
            renderTrends();
        }
        // Detail page doesn't have charts, no refresh needed
    } catch (err) {
        console.error('[Theme] Error refreshing page for theme change:', err);
    }
}
