/**
 * Calendar page - Team absence entry and pending JSON export.
 */

import { D } from '../state';
import type { CalendarAbsenceEntry } from '../types/dashboard';

type AbsenceType = 'Holiday' | 'Sickness' | 'Other' | 'Half Day';

type CalendarPayload = {
    version: 1;
    app: 'invoice-process-dashboard';
    created_at: string;
    created_by: string;
    added: Array<{ member: string; date: string; type: AbsenceType }>;
    deleted: Array<{ member: string; date: string }>;
};

type FileSystemPermissionMode = 'read' | 'readwrite';

type StoredDirectoryHandle = {
    kind: 'directory';
    requestPermission?: (descriptor?: { mode?: FileSystemPermissionMode }) => Promise<PermissionState>;
    queryPermission?: (descriptor?: { mode?: FileSystemPermissionMode }) => Promise<PermissionState>;
    getFileHandle: (name: string, options?: { create?: boolean }) => Promise<{
        createWritable: () => Promise<{
            write: (data: Blob) => Promise<void>;
            close: () => Promise<void>;
        }>;
    }>;
};

const ABSENCE_TYPES: AbsenceType[] = ['Holiday', 'Sickness', 'Other', 'Half Day'];
const DB_NAME = 'invoice-calendar-store';
const STORE_NAME = 'handles';
const HANDLE_KEY = 'pending-dir';

let pendingHandle: StoredDirectoryHandle | null = null;

function el(id: string): HTMLElement | null {
    return document.getElementById(id);
}

function escapeHtml(value: string): string {
    return value.replace(/[&<>"']/g, char => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;',
    }[char] || char));
}

function todayIso(): string {
    return new Date().toISOString().slice(0, 10);
}

function sanitizeUser(value: string): string {
    return (value || 'teamleader').trim().replace(/[^A-Za-z0-9._-]+/g, '_') || 'teamleader';
}

function timestampForFilename(dateValue: Date): string {
    const pad = (n: number) => String(n).padStart(2, '0');
    return [
        dateValue.getFullYear(),
        pad(dateValue.getMonth() + 1),
        pad(dateValue.getDate()),
    ].join('-') + '-' + [
        pad(dateValue.getHours()),
        pad(dateValue.getMinutes()),
        pad(dateValue.getSeconds()),
    ].join('-');
}

function setStatus(message: string, tone: 'ok' | 'warn' | 'error' = 'ok'): void {
    const status = el('calendarStatus');
    if (!status) return;
    status.textContent = message;
    status.className = `calendar-status ${tone}`;
}

function openDb(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);
        request.onupgradeneeded = () => {
            request.result.createObjectStore(STORE_NAME);
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
}

async function saveHandle(handle: StoredDirectoryHandle): Promise<void> {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        tx.objectStore(STORE_NAME).put(handle, HANDLE_KEY);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
    db.close();
}

async function loadHandle(): Promise<StoredDirectoryHandle | null> {
    const db = await openDb();
    const handle = await new Promise<StoredDirectoryHandle | null>((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const request = tx.objectStore(STORE_NAME).get(HANDLE_KEY);
        request.onsuccess = () => resolve((request.result as StoredDirectoryHandle | undefined) || null);
        request.onerror = () => reject(request.error);
    });
    db.close();
    return handle;
}

async function hasWritePermission(handle: StoredDirectoryHandle): Promise<boolean> {
    const descriptor = { mode: 'readwrite' as FileSystemPermissionMode };
    if (handle.queryPermission && await handle.queryPermission(descriptor) === 'granted') {
        return true;
    }
    if (handle.requestPermission) {
        return await handle.requestPermission(descriptor) === 'granted';
    }
    return false;
}

async function writeToDirectory(filename: string, payload: CalendarPayload): Promise<boolean> {
    if (!pendingHandle || !await hasWritePermission(pendingHandle)) {
        return false;
    }
    const fileHandle = await pendingHandle.getFileHandle(filename, { create: true });
    const writable = await fileHandle.createWritable();
    await writable.write(new Blob([JSON.stringify(payload, null, 2) + '\n'], { type: 'application/json' }));
    await writable.close();
    return true;
}

function downloadJson(filename: string, payload: CalendarPayload): void {
    const blob = new Blob([JSON.stringify(payload, null, 2) + '\n'], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
}

function buildPayload(
    added: CalendarPayload['added'],
    deleted: CalendarPayload['deleted'],
): { filename: string; payload: CalendarPayload } {
    const userInput = document.getElementById('calendarUser') as HTMLInputElement | null;
    const user = sanitizeUser(userInput?.value || localStorage.getItem('invoiceCalendarUser') || '');
    localStorage.setItem('invoiceCalendarUser', user);
    const now = new Date();
    return {
        filename: `invoice_calendar_pending_${timestampForFilename(now)}_${user}.json`,
        payload: {
            version: 1,
            app: 'invoice-process-dashboard',
            created_at: now.toISOString(),
            created_by: user,
            added,
            deleted,
        },
    };
}

async function savePayload(payload: CalendarPayload, filename: string): Promise<void> {
    try {
        if (await writeToDirectory(filename, payload)) {
            setStatus(`Saved ${filename}`, 'ok');
            return;
        }
    } catch (err) {
        console.warn('[Calendar] Direct save failed, using download fallback.', err);
    }
    downloadJson(filename, payload);
    setStatus(`Downloaded ${filename}`, 'warn');
}

function sortedAbsences(): CalendarAbsenceEntry[] {
    return [...(D.calendar_absences || [])].sort((a, b) => (
        a.date.localeCompare(b.date) || a.member.localeCompare(b.member)
    ));
}

function renderTableRows(absences: CalendarAbsenceEntry[]): string {
    if (!absences.length) {
        return '<tr><td colspan="5" class="calendar-empty">No absences found</td></tr>';
    }
    return absences.map(row => `
        <tr>
          <td>${escapeHtml(row.date)}</td>
          <td>${escapeHtml(row.member)}</td>
          <td><span class="calendar-type">${escapeHtml(row.type)}</span></td>
          <td><span class="calendar-source">${escapeHtml(row.source || 'weekly_overrides')}</span></td>
          <td>
            <button class="calendar-icon-btn" title="Delete absence" onclick="deleteCalendarAbsence('${escapeHtml(row.member)}','${escapeHtml(row.date)}')">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/></svg>
            </button>
          </td>
        </tr>
    `).join('');
}

export async function renderCalendar(): Promise<void> {
    const page = el('pageCalendar');
    if (!page) return;

    const savedUser = localStorage.getItem('invoiceCalendarUser') || 'teamleader';
    const absences = sortedAbsences();
    page.innerHTML = `
      <div class="page-header">
        <div>
          <h1 class="page-title">Calendar</h1>
          <p class="page-subtitle">Absence entries for Holiday, Sickness, Other and Half Day</p>
        </div>
        <button class="calendar-connect-btn" onclick="connectCalendarFolder()">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20h16"/><path d="M12 4v12"/><path d="m6 10 6 6 6-6"/></svg>
          Connect Folder
        </button>
      </div>

      <div class="calendar-grid">
        <section class="calendar-panel">
          <div class="section-title">Add Absence</div>
          <div class="calendar-form">
            <label>Member<select id="calendarMember">${D.team_members.map(m => `<option value="${escapeHtml(m)}">${escapeHtml(m)}</option>`).join('')}</select></label>
            <label>Date<input id="calendarDate" type="date" value="${todayIso()}"></label>
            <label>Type<select id="calendarType">${ABSENCE_TYPES.map(t => `<option value="${t}">${t}</option>`).join('')}</select></label>
            <label>Saved By<input id="calendarUser" type="text" value="${escapeHtml(savedUser)}"></label>
            <button class="calendar-save-btn" onclick="saveCalendarAbsence()">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8"/><path d="M7 3v5h8"/></svg>
              Save
            </button>
          </div>
          <div id="calendarStatus" class="calendar-status">Ready</div>
        </section>

        <section class="calendar-panel">
          <div class="section-title">Current Absences</div>
          <div class="calendar-table-wrap">
            <table class="calendar-table">
              <thead><tr><th>Date</th><th>Member</th><th>Type</th><th>Source</th><th></th></tr></thead>
              <tbody>${renderTableRows(absences)}</tbody>
            </table>
          </div>
        </section>
      </div>
    `;

    try {
        pendingHandle = await loadHandle();
        if (pendingHandle) {
            setStatus('Folder connected', 'ok');
        }
    } catch (err) {
        console.warn('[Calendar] Stored folder handle unavailable.', err);
    }
}

async function connectCalendarFolder(): Promise<void> {
    const picker = (window as unknown as {
        showDirectoryPicker?: (options?: { id?: string; mode?: FileSystemPermissionMode; startIn?: string }) => Promise<StoredDirectoryHandle>;
    }).showDirectoryPicker;
    if (!picker) {
        setStatus('Direct folder save is not available in this browser', 'warn');
        return;
    }
    try {
        pendingHandle = await picker({
            id: 'invoice-calendar-pending-dir',
            mode: 'readwrite',
            startIn: 'documents',
        });
        await saveHandle(pendingHandle);
        setStatus('Folder connected', 'ok');
    } catch (err) {
        console.warn('[Calendar] Folder connection cancelled or failed.', err);
        setStatus('Folder not connected', 'warn');
    }
}

async function saveCalendarAbsence(): Promise<void> {
    const member = (document.getElementById('calendarMember') as HTMLSelectElement | null)?.value || '';
    const date = (document.getElementById('calendarDate') as HTMLInputElement | null)?.value || '';
    const type = (document.getElementById('calendarType') as HTMLSelectElement | null)?.value as AbsenceType;
    if (!member || !date || !ABSENCE_TYPES.includes(type)) {
        setStatus('Missing member, date or type', 'error');
        return;
    }
    const { filename, payload } = buildPayload([{ member, date, type }], []);
    await savePayload(payload, filename);
}

async function deleteCalendarAbsence(member: string, date: string): Promise<void> {
    const { filename, payload } = buildPayload([], [{ member, date }]);
    await savePayload(payload, filename);
}

export const calendarWindowBindings = {
    connectCalendarFolder,
    saveCalendarAbsence,
    deleteCalendarAbsence,
};
