/** Get individual target for a member */
function getTarget(m: string): number {
    return (D.individual_targets?.[m]) || D.daily_target;
}

/**
 * Build absence badge HTML for a member.
 * Returns '' when no absences exist for the member that week.
 */
function buildAbsenceBadge(
    absences: Record<string, AbsenceEntry[]> | undefined,
    member: string
): string {
    const entries = absences?.[member];
    if (!entries || entries.length === 0) return '';

    const total = entries.reduce((sum, e) => sum + (e.type === 'Half Day' ? 0.5 : 1), 0);

    // Pick icon for the most frequent absence type
    const counts: Record<string, number> = {};
    entries.forEach(e => { counts[e.type] = (counts[e.type] || 0) + 1; });
    const dominant = Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0];
    const ICONS: Record<string, string> = { Holiday: '', Sickness: '', Other: '', 'Half Day': '' };
    const icon = ICONS[dominant] ?? '';

    // Tooltip: "Holiday: 20/03, 23/03"
    const dateList = entries
        .map(e => {
            const parts = e.date.split('-');
            return `${parts[2]}/${parts[1]}`;
        })
        .join(', ');
    const tooltip = `${dominant}: ${dateList}`;

    return ` <span title="${escapeHtml(tooltip)}" style="font-size:.72rem;padding:.1rem .3rem;border-radius:3px;background:var(--amber-soft);color:var(--amber);cursor:default">${icon} ${total}d</span>`;
}

function getDailyAbsence(
    absences: Record<string, AbsenceEntry[]> | undefined,
    member: string,
    date: string
): AbsenceEntry | undefined {
    return absences?.[member]?.find(entry => entry.date === date);
}

function absenceClass(type: AbsenceEntry['type']): string {
    return `dt-absence-${type.toLowerCase().replace(/\s+/g, '-')}`;
}

function buildDailyCell(
    member: string,
    date: string,
    value: number,
    target: number,
    absence: AbsenceEntry | undefined
): string {
    const met = value >= target;
    const statusClass = met ? 'dt-hit' : value > 0 ? 'dt-partial' : 'dt-miss';
    const classes = ['dt-col', 'dt-cell', statusClass];
    if (absence) classes.push('dt-has-absence', absenceClass(absence.type));
    if (value > 0) classes.push('dt-has-production');

    const production = value > 0 ? fmt(value) : '-';
    const absenceHtml = absence
        ? `<span class="dt-absence" title="${escapeHtml(`${absence.type} on ${date}`)}">${escapeHtml(absence.type)}</span>`
        : '';

    return `<td class="${classes.join(' ')}" data-member="${escapeHtml(member)}" data-date="${date}">
        <span class="dt-production">${production}</span>${absenceHtml}
    </td>`;
}

function parseIsoDate(value: string): Date | null {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (!match) return null;

    const parsed = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function formatIsoDate(value: Date): string {
    const year = value.getFullYear();
    const month = String(value.getMonth() + 1).padStart(2, '0');
    const day = String(value.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function buildDisplayDates(week: FilteredWeek): string[] {
    const dates = new Set<string>(Object.keys(week.daily || {}));

    Object.values(week.absences || {}).forEach(entries => {
        entries.forEach(entry => dates.add(entry.date));
    });

    const start = parseIsoDate(week.week_start);
    const end = parseIsoDate(week.week_end);
    if (start && end && start <= end) {
        const cursor = new Date(start);
        while (cursor <= end) {
            const day = cursor.getDay();
            if (day !== 0 && day !== 6) {
                dates.add(formatIsoDate(cursor));
            }
            cursor.setDate(cursor.getDate() + 1);
        }
    }

    return [...dates].sort();
}

/** Filtered week data with computed aggregations */
interface ProcessedWeekData {
    week: FilteredWeek;
    members: string[];
    dates: string[];
    totals: Record<string, FilteredMemberDay>;
    dailyData: Record<string, Record<string, number>>;
    target: number;
    workingDays: number;
    weekTarget: number;
}

/**
 * Get filtered week data respecting all active filters.
 * @param weekIdx - Week index (defaults to currentWeekIdx)
 * @returns Processed week data or null if not available
 */
export async function getFilteredWeek(weekIdx?: number): Promise<ProcessedWeekData | null> {
    try {
        const weekIndex = getWeekIndex();
        if (!weekIndex.length) return null;

        const idx = weekIdx !== undefined ? weekIdx : currentWeekIdx;
        if (idx >= weekIndex.length) return null;

        const week = weekIdx === undefined && (dateRangeFrom || dateRangeTo)
            ? await getFullWeekMergedForRange(dateRangeFrom, dateRangeTo)
            : await getFullWeekMerged(Math.min(idx, weekIndex.length - 1));
        if (!week) return null;

        const members = filterOwner === 'all' ? D.team_members : [filterOwner];
        const dates = buildDisplayDates(week);
        const target = D.daily_target;
        const workingDays = week.working_days || D.working_days || 5;
        const weekDaysForTarget = workingDays;
        const weekTarget = target * weekDaysForTarget;

        const totals: Record<string, FilteredMemberDay> = {};
        const dailyData: Record<string, Record<string, number>> = {};

        members.forEach(m => {
            totals[m] = {
                total: 0,
                by_country: {},
                by_doc_type: {},
                reversal_count: 0,
                credit_note_count: 0,
                member: m
            };
        });

        dates.forEach(date => {
            dailyData[date] = {};
            members.forEach(m => {
                const raw = week.daily[date]?.[m];
                if (!raw) {
                    dailyData[date][m] = 0;
                    return;
                }

                let count = raw.total;

                // Apply country filter
                if (filterCountry !== 'all') {
                    count = raw.by_country?.[filterCountry] || 0;
                }

                // Apply doc type filter
                if (filterDocType !== 'all') {
                    count = raw.by_doc_type?.[filterDocType] || 0;
                }

                dailyData[date][m] = count;
                totals[m].total += count;

                // Country breakdown
                if (filterCountry === 'all') {
                    Object.entries(raw.by_country || {}).forEach(([c, n]) => {
                        totals[m].by_country[c] = (totals[m].by_country[c] || 0) + n;
                    });
                } else {
                    const cc = raw.by_country?.[filterCountry] || 0;
                    if (cc > 0) {
                        totals[m].by_country[filterCountry] = (totals[m].by_country[filterCountry] || 0) + cc;
                    }
                }

                // Doc type breakdown
                if (filterDocType === 'all') {
                    Object.entries(raw.by_doc_type || {}).forEach(([d, c]) => {
                        totals[m].by_doc_type[d] = (totals[m].by_doc_type[d] || 0) + c;
                    });
                } else {
                    const dc = raw.by_doc_type?.[filterDocType] || 0;
                    if (dc > 0) {
                        totals[m].by_doc_type[filterDocType] = (totals[m].by_doc_type[filterDocType] || 0) + dc;
                    }
                }

                // Quality: reversals & credit notes (always full, not filtered)
                totals[m].reversal_count += raw.reversal_count || 0;
                totals[m].credit_note_count += raw.credit_note_count || 0;
            });
        });

        // Cards/KPIs use the exporter-owned weekly aggregates. Daily rows stay
        // detail-faithful so an aggregate override never creates fake invoices.
        const hasWeeklyAggregates = Object.values(week.weekly_totals || {}).some(row => (
            row.total > 0 || Object.keys(row.by_country || {}).length > 0 || Object.keys(row.by_doc_type || {}).length > 0
        ));
        if (filterCountry === 'all' && filterDocType === 'all' && hasWeeklyAggregates) {
            members.forEach(m => {
                const raw = week.weekly_totals[m];
                if (!raw) return;
                totals[m] = {
                    total: raw.total || 0,
                    by_country: { ...(raw.by_country || {}) },
                    by_doc_type: { ...(raw.by_doc_type || {}) },
                    reversal_count: raw.reversal_count || 0,
                    credit_note_count: raw.credit_note_count || 0,
                    member: m,
                };
            });
        }

        return { week, members, dates, totals, dailyData, target, workingDays, weekTarget };
    } catch (err) {
        console.error('[Overview] Error loading filtered week data:', err);
        return null;
    }
}

/**
 * Main overview page renderer.
 * Loads week data and renders all components.
 */
export async function loadWeek(): Promise<void> {
    const el = document.getElementById('pageOverview');
    if (!el) return;

    try {
        const f = await getFilteredWeek();
        const viewLabel = getTypeLabel();

        if (!f) {
            el.innerHTML = `<div class="page-header fade-in"><div><div class="page-title">Overview  ${escapeHtml(viewLabel)}</div><div class="page-subtitle">No data available for this view</div></div></div>`;
            return;
        }

        const { week, members, totals, workingDays } = f;

        // Update extraction info
        const extractionEl = document.getElementById('extractionInfo');
        if (extractionEl) {
            extractionEl.textContent = `Extracted: ${week.extraction_date}`;
        }

        // Calculate current week KPIs
        const totalInvoices = members.reduce((s, m) => s + totals[m].total, 0);
        const dailyAvg = Math.round(totalInvoices / workingDays);
        const activeCount = members.filter(m => totals[m].total > 0).length;
        const weekDaysForTarget = workingDays;
        const teamTarget = members.reduce((s, m) => {
            const md = week.working_days_per_member?.[m] ?? weekDaysForTarget;
            return s + getTarget(m) * md;
        }, 0);
        const ach = pct(totalInvoices, teamTarget);

        // Quality metrics
        const totalReversals = members.reduce((s, m) => s + totals[m].reversal_count, 0);
        const totalCreditNotes = members.reduce((s, m) => s + totals[m].credit_note_count, 0);
        const qualityScore = totalInvoices > 0
            ? 100 - pct(totalReversals + totalCreditNotes, totalInvoices)
            : 100;

        // Blocked invoices count from detail invoice data
        const allInvoices = await getInvoices();
        const weekInvoices = allInvoices.filter((inv: Invoice) => {
            // Filter to current reporting date range.
            const invoiceDate = inv.entry_date || inv.posting_date;
            if (invoiceDate < week.week_start || invoiceDate > week.week_end) return false;

            // Apply type filter (manual/csv/envoy)
            const hasM = activeTypes.has('manual');
            const hasC = activeTypes.has('csv');
            const hasEn = activeTypes.has('envoy');
            if (inv.is_csv === 0 && !hasM) return false;
            if (inv.is_csv === 1 && !hasC) return false;
            if (inv.is_csv === 2 && !hasEn) return false;

            // Apply member filter
            if (filterOwner !== 'all' && inv.team_member !== filterOwner) return false;

            // Apply country filter
            if (filterCountry !== 'all' && inv.country !== filterCountry) return false;

            return true;
        });
        const blockedCount = weekInvoices.filter((inv: Invoice) => (inv.payment_block || '').trim() !== '').length;
        const blockedPct = weekInvoices.length > 0 ? pct(blockedCount, weekInvoices.length) : 0;

        // Previous week comparison
        const prevF = await getFilteredWeek(currentWeekIdx + 1);
        let prevTotal: number | null = null;
        let prevAvg: number | null = null;
        let prevAch: number | null = null;
        let prevTotals: Record<string, number> = {};

        if (prevF) {
            prevTotal = members.reduce((s, m) => s + prevF.totals[m].total, 0);
            prevAvg = Math.round(prevTotal / prevF.workingDays);
            const prevTeamTarget = members.reduce((s, m) => {
                const md = prevF.week.working_days_per_member?.[m] ?? weekDaysForTarget;
                return s + getTarget(m) * md;
            }, 0);
            prevAch = pct(prevTotal, prevTeamTarget);
            members.forEach(m => {
                prevTotals[m] = prevF.totals[m].total;
            });
        }

        // Render HTML
        el.innerHTML = buildPageHeader(week, viewLabel)
            + buildKPIs({
                total: totalInvoices,
                avg: dailyAvg,
                active: activeCount,
                count: members.length,
                ach,
                blockedCount,
                blockedPct,
                qualityScore,
                reversalCount: totalReversals,
                creditNoteCount: totalCreditNotes,
                prevTotal,
                prevAvg,
                prevAch
            })
            + buildMemberCards(f, prevTotals)
            + `<div class="charts-row">
                <div class="chart-card fade-in d5"><div class="section-title">Weekly Summary</div><div class="chart-wrap" style="height:360px"><canvas id="cWeekly"></canvas></div></div>
                <div class="chart-card fade-in d6"><div class="section-title">Document Types</div><div class="chart-wrap" style="height:360px"><canvas id="cDocType"></canvas></div></div>
              </div>`
            + buildDailyTable(f);

        // Render charts
        destroyCharts();
        // Weekly Summary chart shows individual member bars  use individual weekTarget (100  5 = 500), not team total
        const individualWeekTarget = D.daily_target * weekDaysForTarget;
        renderWeeklyChart({
            members,
            totals,
            workingDays,
            weekTarget: individualWeekTarget,
            workingDaysPerMember: week.working_days_per_member,
        });
        renderDocTypeChart({
            members,
            totals,
            workingDays,
            weekTarget: individualWeekTarget
        });
    } catch (err) {
        console.error('[Overview] Error loading week:', err);
        el.innerHTML = '<div class="page-header fade-in"><div><div class="page-title">Overview</div><div class="page-subtitle">Error loading data. Please try again.</div></div></div>';
    }
}

/** Build page header with title and export button */
function buildPageHeader(week: FilteredWeek, viewLabel: string): string {
    return `<div class="page-header fade-in">
    <div><div class="page-title">Overview  ${escapeHtml(viewLabel || 'Manual Post')}</div><div class="page-subtitle">${escapeHtml(week.label)}</div></div>
    <div style="display:flex;align-items:center;gap:.6rem">
      <button class="btn-print" onclick="window.print()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 9V3h12v6"/><rect width="12" height="8" x="6" y="14"/></svg>Export</button>
      <div class="header-badge">${week.week_start}  ${week.week_end}</div>
    </div>
  </div>`;
}

/** Build KPI cards HTML */
function buildKPIs(k: {
    total: number;
    avg: number;
    active: number;
    count: number;
    ach: number;
    blockedCount: number;
    blockedPct: number;
    qualityScore: number;
    reversalCount: number;
    creditNoteCount: number;
    prevTotal: number | null;
    prevAvg: number | null;
    prevAch: number | null;
}): string {
    const ac = k.ach >= 100 ? 'i-green' : k.ach >= 50 ? 'i-amber' : 'i-red';
    const bc = k.blockedPct >= 10 ? 'i-red' : k.blockedPct >= 5 ? 'i-amber' : 'i-green';
    const qc = k.qualityScore >= 95 ? 'i-green' : k.qualityScore >= 90 ? 'i-amber' : 'i-red';

    return `<div class="kpi-row">
    <div class="kpi-card fade-in d1"><div class="kpi-icon i-teal"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6"/><path d="M16 13H8"/><path d="M16 17H8"/><path d="M10 9H8"/></svg></div><div><div class="kpi-label">Total Invoices</div><div class="kpi-value">${fmt(k.total)}${wowBadge(k.total, k.prevTotal)}</div></div></div>
    <div class="kpi-card fade-in d2"><div class="kpi-icon i-green"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg></div><div><div class="kpi-label">Daily Average</div><div class="kpi-value">${fmt(k.avg)}${wowBadge(k.avg, k.prevAvg)}</div></div></div>
    <div class="kpi-card fade-in d3"><div class="kpi-icon i-amber"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></div><div><div class="kpi-label">Members Active</div><div class="kpi-value">${k.active}<span style="font-size:.75rem;color:var(--text-muted);font-weight:400"> / ${k.count}</span></div></div></div>
    <div class="kpi-card fade-in d4"><div class="kpi-icon ${ac}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20V10"/><path d="M18 20V4"/><path d="M6 20v-4"/></svg></div><div><div class="kpi-label">Team Target</div><div class="kpi-value">${k.ach}<span style="font-size:.8rem">%</span>${wowBadge(k.ach, k.prevAch)}</div></div></div>
    <div class="kpi-card fade-in d5"><div class="kpi-icon ${bc}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="11" x="3" y="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg></div><div><div class="kpi-label">Payment Block</div><div class="kpi-value">${k.blockedPct}<span style="font-size:.8rem">%</span> <span style="font-size:.65rem;color:var(--text-muted);font-weight:400">(${fmt(k.blockedCount)})</span></div></div></div>
    <div class="kpi-card fade-in d6"><div class="kpi-icon ${qc}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"/><path d="m9 12 2 2 4-4"/></svg></div><div><div class="kpi-label">Quality Score</div><div class="kpi-value">${k.qualityScore}<span style="font-size:.8rem">%</span> <span style="font-size:.65rem;color:var(--text-muted);font-weight:400">(${fmt(k.reversalCount)} rev. / ${fmt(k.creditNoteCount || 0)} CN)</span></div></div></div>
  </div>`;
}

/** Build member cards grid HTML */
function buildMemberCards(f: ProcessedWeekData, prevTotals: Record<string, number>): string {
    const { members, totals } = f;
    const weekDaysForTarget = f.workingDays || D.working_days || 5;

    // When only Envoy is selected, hide members with 0 postings
    const onlyEnvoy = activeTypes.has('envoy') && !activeTypes.has('manual') && !activeTypes.has('csv');
    const visibleMembers = onlyEnvoy ? members.filter(m => totals[m].total > 0) : members;

    // Compute rankings
    const ranked = [...visibleMembers]
        .map(m => ({ name: m, total: totals[m].total }))
        .sort((a, b) => b.total - a.total);
    const rankMap: Record<string, number> = {};
    ranked.forEach((r, i) => { rankMap[r.name] = i + 1; });

    const prevRankMap: Record<string, number> = {};
    if (prevTotals && Object.keys(prevTotals).length > 0) {
        const prevRanked = [...visibleMembers]
            .map(m => ({ name: m, total: prevTotals[m] || 0 }))
            .sort((a, b) => b.total - a.total);
        prevRanked.forEach((r, i) => { prevRankMap[r.name] = i + 1; });
    }

    let h = '<div class="members-grid">';
    visibleMembers.forEach((m, i) => {
        const t = totals[m].total;
        const mTarget = getTarget(m);
        const memberDays = f.week.working_days_per_member?.[m] ?? weekDaysForTarget;
        const mWeekTarget = mTarget * memberDays;
        const avg = (t / memberDays).toFixed(1);
        const p = pct(t, mWeekTarget);
        const cap = Math.min(p, 100);
        const col = p >= 100 ? 'var(--green)' : p >= 50 ? 'var(--amber)' : 'var(--red)';
        const bg = p >= 100 ? 'var(--green-soft)' : p >= 50 ? 'var(--amber-soft)' : 'var(--red-soft)';
        const idx = D.team_members.indexOf(m);

        // Rank badge
        const rank = rankMap[m];
        const rankCls = rank <= 3 ? ` rank-${rank}` : '';
        const medal = rank === 1 ? ' ' : rank === 2 ? ' ' : rank === 3 ? ' ' : '';
        let rankHtml = `<span class="rank-badge${rankCls}">${medal}${ordinal(rank)}</span>`;
        if (prevTotals && prevRankMap[m]) {
            const diff = prevRankMap[m] - rank;
            if (diff > 0) rankHtml += `<span class="rank-change up">${diff}</span>`;
            else if (diff < 0) rankHtml += `<span class="rank-change down">${Math.abs(diff)}</span>`;
            else rankHtml += `<span class="rank-change same"></span>`;
        }

        // Warning for below 50%
        const warning = p < 50 && t > 0 ? '<div class="mc-warning" title="Below 50% of target"></div>' : '';

        // Country pills
        const ctrs = Object.entries(totals[m].by_country || {}).sort((a, b) => b[1] - a[1]);
        const cPills = ctrs.length
            ? ctrs.map(([c, n]) => `<span class="sys-pill">${escapeHtml(c)}: ${fmt(n)}</span>`).join('')
            : '<span class="sys-pill"></span>';

        // Doc type pills (top 3)
        const dts = Object.entries(totals[m].by_doc_type || {})
            .sort((a, b) => b[1] - a[1])
            .slice(0, 3);
        const dtPills = dts.length
            ? dts.map(([dt, n]) => `<span class="dtype-pill">${escapeHtml(D.doc_type_labels[dt] || dt)}: ${fmt(n)}</span>`).join('')
            : '';

        // Quality pills
        const mRevCount = totals[m].reversal_count || 0;
        const mCNCount = getCreditNoteCount(totals[m].by_doc_type || {});
        const mQualCount = mRevCount + mCNCount;
        const mQualPct = t > 0 ? pct(mQualCount, t) : 0;
        const qCls = mQualPct > 5 ? 'q-bad' : mQualPct > 2 ? 'q-warn' : 'q-good';
        let qPill = '';
        if (mRevCount > 0) qPill += `<span class="quality-pill ${qCls}">${mRevCount} rev.</span>`;
        if (mCNCount > 0) qPill += `<span class="quality-pill q-cn">${mCNCount} CN</span>`;

        h += `<div class="member-card fade-in d${i + 1}" data-i="${idx}" data-member="${escapeHtml(m)}" onclick="selectMember('${escapeHtml(m).replace(/'/g, "\\'")}')">
      ${warning}
      <div class="mc-rank">${rankHtml}</div>
      <div class="mc-top"><div><div class="mc-name">${escapeHtml(m)}${buildAbsenceBadge(f.week.absences, m)}${qPill}</div><div class="mc-count" style="color:${getMemberColor(idx)}">${fmt(t)}</div><div class="mc-avg">${avg} / day</div></div>
      <div class="target-ring" style="background:conic-gradient(${col} ${cap * 3.6}deg,${bg} ${cap * 3.6}deg 360deg)"><div class="target-ring-inner" style="color:${col}">${p}%</div></div></div>
      <div class="mc-systems">${cPills}</div>
      ${dtPills ? `<div class="mc-doctypes">${dtPills}</div>` : ''}
    </div>`;
    });

    return h + '</div>';
}

/** Build daily breakdown table HTML */
function buildDailyTable(f: ProcessedWeekData): string {
    const { members, dates, dailyData } = f;
    const weekDaysForTarget = f.workingDays || D.working_days || 5;

    let h = `<div class="table-card fade-in d7">
    <div class="section-title">Daily Breakdown</div>
    <div class="table-responsive"><table class="daily-table"><thead><tr><th class="dt-name">Team Member</th>`;

    dates.forEach(d => {
        const dt = new Date(d + 'T00:00:00');
        const day = DAY_NAMES[dt.getDay()];
        h += `<th class="dt-col">${day}<br><span class="dt-date">${d}</span></th>`;
    });

    h += `<th class="dt-total">Total</th><th class="dt-avg">Avg/Day</th><th class="dt-target">Target</th></tr></thead><tbody>`;

    members.forEach(m => {
        const mTarget = getTarget(m);
        const memberDays = f.week.working_days_per_member?.[m] ?? weekDaysForTarget;
        const mWeekTarget = mTarget * memberDays;
        const total = dates.reduce((s, d) => s + dailyData[d][m], 0);
        const avg = (total / memberDays).toFixed(1);
        const targetMet = total >= mWeekTarget;

        h += `<tr><td class="dt-name">${escapeHtml(m)}${buildAbsenceBadge(f.week.absences, m)}</td>`;
        dates.forEach(d => {
            const val = dailyData[d][m];
            h += buildDailyCell(m, d, val, mTarget, getDailyAbsence(f.week.absences, m, d));
        });

        const tCls = targetMet ? 'dt-hit' : total > 0 ? 'dt-partial' : 'dt-miss';
        h += `<td class="dt-total ${tCls}">${fmt(total)}</td><td class="dt-avg">${avg}</td><td class="dt-target">${mWeekTarget}</td></tr>`;
    });

    h += `</tbody></table></div></div>`;
    return h;
}
