/**
 * data-merge.ts - Utilities for merging and aggregating week data.
 */

import { D } from '../state';
import { CREDIT_NOTE_TYPES } from '../config';
import type { MemberDay } from '../types/dashboard';
import type { FilteredWeek } from '../types/filtered';

/**
 * Calculate total credit note count from document type breakdown.
 * @param byDocType - Document type breakdown (e.g., { KG: 5, ST: 2, ... })
 * @returns Total count of credit note types (KG, ST, 1R)
 */
export function getCreditNoteCount(byDocType: Record<string, number>): number {
    return CREDIT_NOTE_TYPES.reduce((sum, dt) => sum + (byDocType[dt] || 0), 0);
}

/**
 * Merge two week data objects by summing all metrics.
 * Used to combine manual + CSV + Envoy data based on active type filters.
 *
 * @param w1 - First week data
 * @param w2 - Second week data
 * @returns Merged week data
 */
export function mergeWeekData(w1: FilteredWeek, w2: FilteredWeek): FilteredWeek {
    const merged: FilteredWeek = {
        week_start: w1.week_start,
        week_end: w1.week_end,
        extraction_date: w1.extraction_date,
        label: w1.label,
        daily: {},
        weekly_totals: {},
        working_days: 1,
        // Absence data is week-level  same across manual/csv/envoy blobs for same week
        working_days_per_member: w1.working_days_per_member ?? w2.working_days_per_member,
        absences: w1.absences ?? w2.absences,
    };

    // Merge daily data
    const allDates = new Set([
        ...Object.keys(w1.daily),
        ...Object.keys(w2.daily)
    ]);

    // Include former members so their historical data survives the merge (trends/totals).
    const mergeMembers = [...D.team_members, ...(D.former_members || [])];

    allDates.forEach(date => {
        merged.daily[date] = {};
        mergeMembers.forEach(m => {
            const a: MemberDay = w1.daily[date]?.[m] || {
                total: 0,
                by_country: {},
                by_doc_type: {},
                reversal_count: 0,
                credit_note_count: 0
            };
            const b: MemberDay = w2.daily[date]?.[m] || {
                total: 0,
                by_country: {},
                by_doc_type: {},
                reversal_count: 0,
                credit_note_count: 0
            };

            // Merge by_country
            const bc = { ...a.by_country };
            Object.entries(b.by_country).forEach(([k, v]) => {
                bc[k] = (bc[k] || 0) + v;
            });

            // Merge by_doc_type
            const bd = { ...a.by_doc_type };
            Object.entries(b.by_doc_type).forEach(([k, v]) => {
                bd[k] = (bd[k] || 0) + v;
            });

            merged.daily[date][m] = {
                total: a.total + b.total,
                by_country: bc,
                by_doc_type: bd,
                reversal_count: (a.reversal_count || 0) + (b.reversal_count || 0),
                credit_note_count: (a.credit_note_count || 0) + (b.credit_note_count || 0)
            };
        });
    });

    merged.working_days = allDates.size || 1;

    // Merge weekly totals
    mergeMembers.forEach(m => {
        const a: MemberDay = w1.weekly_totals[m] || {
            total: 0,
            by_country: {},
            by_doc_type: {},
            reversal_count: 0,
            credit_note_count: 0
        };
        const b: MemberDay = w2.weekly_totals[m] || {
            total: 0,
            by_country: {},
            by_doc_type: {},
            reversal_count: 0,
            credit_note_count: 0
        };

        // Merge by_country
        const bc = { ...a.by_country };
        Object.entries(b.by_country).forEach(([k, v]) => {
            bc[k] = (bc[k] || 0) + v;
        });

        // Merge by_doc_type
        const bd = { ...a.by_doc_type };
        Object.entries(b.by_doc_type).forEach(([k, v]) => {
            bd[k] = (bd[k] || 0) + v;
        });

        merged.weekly_totals[m] = {
            total: a.total + b.total,
            by_country: bc,
            by_doc_type: bd,
            reversal_count: (a.reversal_count || 0) + (b.reversal_count || 0),
            credit_note_count: (a.credit_note_count || 0) + (b.credit_note_count || 0)
        };
    });

    return merged;
}
