/**
 * chunk-loader.ts - Dynamic loading of Tier 3 historical week chunks.
 *
 * Loads data_chunks/week_YYYY-MM-DD.js files on demand via <script> tags.
 * Each chunk sets window.WEEK_YYYY_MM_DD with compressed week data for all types.
 * Works with file:// protocol (no fetch/CORS issues).
 */

import { D } from '../state';

/** Track in-flight chunk loads to avoid duplicate requests */
const loadingChunks = new Map<string, Promise<void>>();

/** Track already-loaded week_starts */
const loadedChunks = new Set<string>();

/**
 * Find the week_start for a given extraction_date by searching week indexes.
 * @param extractionDate - Extraction date string (YYYY-MM-DD)
 * @returns week_start string or null if not found
 */
function findWeekStart(extractionDate: string): string | null {
    const indexes = [
        D.manual_week_index || [],
        D.csv_week_index || [],
        D.envoy_week_index || [],
    ];

    for (const idx of indexes) {
        const entry = idx.find(w => w.extraction_date === extractionDate);
        if (entry) return entry.week_start;
    }

    return null;
}

/**
 * Convert a week_start date to the window variable name.
 * "2026-02-06"  "WEEK_2026_02_06"
 */
function weekStartToVarName(weekStart: string): string {
    return `WEEK_${weekStart.replace(/-/g, '_')}`;
}

/**
 * Load a chunk file via <script> tag and register its data in D.compressed_weeks.
 * @param weekStart - The week_start date (YYYY-MM-DD)
 * @returns Promise that resolves when chunk is loaded and registered
 */
function loadChunkFile(weekStart: string): Promise<void> {
    // Already loaded
    if (loadedChunks.has(weekStart)) {
        return Promise.resolve();
    }

    // In-flight  return existing promise
    const existing = loadingChunks.get(weekStart);
    if (existing) return existing;

    const promise = new Promise<void>((resolve, reject) => {
        const script = document.createElement('script');
        script.src = `data_chunks/week_${weekStart}.js`;

        script.onload = () => {
            try {
                const varName = weekStartToVarName(weekStart);
                const chunkData = (window as any)[varName];

                if (!chunkData || !chunkData.compressed_weeks) {
                    console.warn('[ChunkLoader] Chunk loaded but no data:', varName);
                    resolve();
                    return;
                }

                const meta = chunkData.meta;
                const ed = meta?.extraction_date;

                if (!ed) {
                    console.warn('[ChunkLoader] Chunk missing extraction_date:', varName);
                    resolve();
                    return;
                }

                // Register ALL types from chunk into D.compressed_weeks
                for (const [typeName, b64] of Object.entries(chunkData.compressed_weeks)) {
                    const key = `${typeName}_${ed}`;
                    D.compressed_weeks[key] = b64 as string;
                }

                loadedChunks.add(weekStart);

                // Clean up window variable to free memory
                delete (window as any)[varName];
            } catch (err) {
                console.error('[ChunkLoader] Error processing chunk:', weekStart, err);
            }

            resolve();
        };

        script.onerror = () => {
            console.error('[ChunkLoader] Failed to load chunk:', script.src);
            reject(new Error(`Failed to load chunk: week_${weekStart}.js`));
        };

        document.head.appendChild(script);
    });

    loadingChunks.set(weekStart, promise);

    // Clean up loading map after completion
    promise.finally(() => {
        loadingChunks.delete(weekStart);
    });

    return promise;
}

/**
 * Ensure a week's chunk data is available in D.compressed_weeks.
 *
 * If the key exists in compressed_weeks (core week), returns immediately.
 * If not, loads the corresponding chunk file from data_chunks/.
 *
 * @param key - Week cache key (e.g., "manual_2026-02-13")
 * @returns true if data is now available, false if not
 */
export async function ensureWeekData(key: string): Promise<boolean> {
    try {
        // Already in core data  nothing to do
        if (D.compressed_weeks[key]) return true;

        // Not chunked or no chunk info  data doesn't exist
        if (!D.chunked || !D.chunk_week_starts?.length) return false;

        // Parse key: "manual_2026-02-13"  type="manual", extractionDate="2026-02-13"
        const underscoreIdx = key.indexOf('_');
        if (underscoreIdx < 0) return false;

        const extractionDate = key.substring(underscoreIdx + 1);

        // Find which week_start this extraction_date belongs to
        const weekStart = findWeekStart(extractionDate);
        if (!weekStart) return false;

        // Check if this week_start has a chunk file
        if (!D.chunk_week_starts.includes(weekStart)) return false;

        // Load the chunk
        await loadChunkFile(weekStart);

        // Verify the key is now available
        return !!D.compressed_weeks[key];
    } catch (err) {
        console.error('[ChunkLoader] Error ensuring week data:', key, err);
        return false;
    }
}
