/**
 * chart-utils.ts - Shared Chart.js utilities and configuration.
 */

import { charts, setCharts } from '../state';
import { Chart } from 'chart.js';

/**
 * Destroy all active Chart.js instances and clear registry.
 * Call before re-rendering charts to prevent memory leaks.
 */
export function destroyCharts(): void {
    Object.values(charts).forEach(c => c?.destroy());
    setCharts({});
}

/**
 * Initialize Chart.js global defaults.
 * Sets font family, colors, legend styles, and grid colors.
 */
export function initChartDefaults(): void {
    // Font configuration
    Chart.defaults.font.family = "'DM Sans',system-ui,sans-serif";
    Chart.defaults.font.size = 12;
    Chart.defaults.color = '#8896b3';

    // Legend configuration
    Chart.defaults.plugins.legend.labels.usePointStyle = true;
    Chart.defaults.plugins.legend.labels.pointStyleWidth = 8;
    Chart.defaults.plugins.legend.labels.padding = 14;
    Chart.defaults.plugins.legend.labels.color = '#8896b3';

    // Grid and borders
    Chart.defaults.scale.grid.color = 'rgba(255,255,255,.04)';
    Chart.defaults.scale.border.color = 'rgba(255,255,255,.06)';
}

/**
 * Get member color from palette by index.
 * @param i - Team member index
 * @returns Hex color string
 */
export function getMemberColor(i: number): string {
    const MC = ['#0ea5e9', '#a78bfa', '#34d399', '#fbbf24', '#f87171', '#f472b6', '#22d3ee'];
    return MC[i % MC.length];
}
