/**
 * detail-filters.ts - Detail page filter management and state.
 */

import { D } from '../state';
import { getInvoices } from '../utils/decompression';

// Detail page filter state
export let detailPage = 1;
export let detailPerPage = 20;
export let detailSort = { col: 'entry_date', dir: 'desc' as 'asc' | 'desc' };
export let detailFilterText = '';
export let detailFilterDateFrom = ''; // Show all weeks by default
export let detailFilterDateTo = '';   // Show all weeks by default
export let detailFilterMember = 'all';
export let detailFilterCountry = 'all';
export let detailActiveTypes = new Set<'manual' | 'csv' | 'envoy'>(['manual', 'csv', 'envoy']);
export let detailFilterDocTypes = new Set<string>(); // empty = show all
export let detailFilterBlocks = new Set<string>(); // empty = show all
export let detailFilterDuplicates = false;

// Setters
export function setDetailPage(page: number): void { detailPage = page; }
export function setDetailPerPage(perPage: number): void { detailPerPage = perPage; }
export function setDetailSort(col: string, dir: 'asc' | 'desc'): void { detailSort = { col, dir }; }
export function setDetailFilterText(text: string): void { detailFilterText = text; }
export function setDetailFilterDateFrom(date: string): void { detailFilterDateFrom = date; }
export function setDetailFilterDateTo(date: string): void { detailFilterDateTo = date; }
export function setDetailFilterMember(member: string): void { detailFilterMember = member; }
export function setDetailFilterCountry(country: string): void { detailFilterCountry = country; }
export function setDetailActiveTypes(types: Set<'manual' | 'csv' | 'envoy'>): void { detailActiveTypes = types; }
export function setDetailFilterDocTypes(types: Set<string>): void { detailFilterDocTypes = types; }
export function setDetailFilterBlocks(blocks: Set<string>): void { detailFilterBlocks = blocks; }
export function setDetailFilterDuplicates(enabled: boolean): void { detailFilterDuplicates = enabled; }

/**
 * Build document type multi-select dropdown for Detail page.
 */
export function buildDtDocTypeDropdown(): void {
    const dd = document.getElementById('msDtDocTypeDropdown');
    if (!dd) return;

    const sorted = D.all_doc_types || [];
    let h = '';
    sorted.forEach(dt => {
        const label = D.doc_type_labels[dt] ? `${dt}  ${D.doc_type_labels[dt]}` : dt;
        const chk = detailFilterDocTypes.has(dt) ? 'checked' : '';
        h += `<div class="ms-option"><input type="checkbox" id="msdt_${dt}" value="${dt}" ${chk} onchange="toggleDtDocTypeOption(this)"><label for="msdt_${dt}">${label}</label></div>`;
    });
    h += `<div class="ms-clear" onclick="clearDtDocTypeFilter()">Clear All</div>`;
    dd.innerHTML = h;
    updateDtDocTypeBtnLabel();
}

/**
 * Build payment block multi-select dropdown.
 * Reads unique values from decompressed invoices.
 */
export async function buildBlockDropdown(): Promise<void> {
    const dd = document.getElementById('msBlockDropdown');
    if (!dd) return;

    try {
        // Collect unique block values from decompressed invoices
        const invs = await getInvoices();
        const blocks = new Set<string>();
        let hasEmpty = false;
        invs.forEach(r => {
            const v = (r.payment_block || '').trim();
            if (v) blocks.add(v);
            else hasEmpty = true;
        });
        const sorted = [...blocks].sort();

        let h = '';
        if (hasEmpty) {
            const chk = detailFilterBlocks.has('__none__') ? 'checked' : '';
            h += `<div class="ms-option"><input type="checkbox" id="msb___none__" value="__none__" ${chk} onchange="toggleBlockOption(this)"><label for="msb___none__">(No Block)</label></div>`;
        }
        sorted.forEach(b => {
            const chk = detailFilterBlocks.has(b) ? 'checked' : '';
            h += `<div class="ms-option"><input type="checkbox" id="msb_${b}" value="${b}" ${chk} onchange="toggleBlockOption(this)"><label for="msb_${b}">${b}</label></div>`;
        });
        h += `<div class="ms-clear" onclick="clearBlockFilter()">Clear All</div>`;
        dd.innerHTML = h;
        updateBlockBtnLabel();
    } catch (err) {
        console.error('[DetailFilters] Error building block dropdown:', err);
    }
}

/**
 * Update doc type button label based on selection.
 */
export function updateDtDocTypeBtnLabel(): void {
    const btn = document.getElementById('msDtDocTypeBtn');
    if (!btn) return;

    if (detailFilterDocTypes.size === 0) {
        btn.textContent = 'All Doc Types';
    } else if (detailFilterDocTypes.size === 1) {
        const dt = [...detailFilterDocTypes][0];
        btn.textContent = D.doc_type_labels[dt] || dt;
    } else {
        btn.textContent = `${detailFilterDocTypes.size} doc types`;
    }
}

/**
 * Update payment block button label based on selection.
 */
export function updateBlockBtnLabel(): void {
    const btn = document.getElementById('msBlockBtn');
    if (!btn) return;

    if (detailFilterBlocks.size === 0) {
        btn.textContent = 'All Blocks';
    } else if (detailFilterBlocks.size === 1) {
        const b = [...detailFilterBlocks][0];
        btn.textContent = b === '__none__' ? '(No Block)' : b;
    } else {
        btn.textContent = `${detailFilterBlocks.size} blocks`;
    }
}

/**
 * Update detail type filter button label.
 */
export function updateDtTypeBtnLabel(): void {
    const btn = document.getElementById('msDtTypeBtn');
    if (!btn) return;

    const types: string[] = [];
    if (detailActiveTypes.has('manual')) types.push('Manual');
    if (detailActiveTypes.has('csv')) types.push('CSV');
    if (detailActiveTypes.has('envoy')) types.push('Envoy');

    if (types.length === 3) {
        btn.textContent = 'All Types';
    } else if (types.length === 0) {
        btn.textContent = 'None';
    } else {
        btn.textContent = types.join(' + ');
    }
}

/**
 * Update member navigation UI in detail page.
 */
export function updateDetailMemberNavUI(): void {
    document.querySelectorAll('.dt-member-btn').forEach((btn: Element) => {
        const htmlBtn = btn as HTMLElement;
        if (htmlBtn.dataset.member === detailFilterMember) {
            htmlBtn.classList.add('active');
        } else {
            htmlBtn.classList.remove('active');
        }
    });
}

// Window bindings for onclick handlers (will be bound in main.ts)
export const detailWindowBindings = {
    toggleDtDocTypeDropdown(): void {
        document.getElementById('msDtDocTypeDropdown')?.classList.toggle('open');
    },

    async toggleDtDocTypeOption(el: HTMLInputElement): Promise<void> {
        try {
            if (el.checked) {
                detailFilterDocTypes.add(el.value);
            } else {
                detailFilterDocTypes.delete(el.value);
            }
            updateDtDocTypeBtnLabel();
            detailPage = 1;

            // Dynamically import to avoid circular dependency
            const { renderDetailRows } = await import('../pages/detail');
            renderDetailRows();
        } catch (err) {
            console.error('[DetailFilters] Error toggling doc type option:', err);
        }
    },

    async clearDtDocTypeFilter(): Promise<void> {
        try {
            detailFilterDocTypes.clear();
            document.querySelectorAll('#msDtDocTypeDropdown input[type="checkbox"]').forEach(cb => {
                (cb as HTMLInputElement).checked = false;
            });
            updateDtDocTypeBtnLabel();
            detailPage = 1;

            const { renderDetailRows } = await import('../pages/detail');
            renderDetailRows();
        } catch (err) {
            console.error('[DetailFilters] Error clearing doc type filter:', err);
        }
    },

    toggleBlockDropdown(): void {
        document.getElementById('msBlockDropdown')?.classList.toggle('open');
    },

    async toggleBlockOption(el: HTMLInputElement): Promise<void> {
        try {
            const val = el.value;
            if (el.checked) {
                detailFilterBlocks.add(val);
            } else {
                detailFilterBlocks.delete(val);
            }
            updateBlockBtnLabel();
            detailPage = 1;

            const { renderDetailRows } = await import('../pages/detail');
            renderDetailRows();
        } catch (err) {
            console.error('[DetailFilters] Error toggling block option:', err);
        }
    },

    async clearBlockFilter(): Promise<void> {
        try {
            detailFilterBlocks.clear();
            document.querySelectorAll('#msBlockDropdown input[type="checkbox"]').forEach(cb => {
                (cb as HTMLInputElement).checked = false;
            });
            updateBlockBtnLabel();
            detailPage = 1;

            const { renderDetailRows } = await import('../pages/detail');
            renderDetailRows();
        } catch (err) {
            console.error('[DetailFilters] Error clearing block filter:', err);
        }
    },

    toggleDtTypeDropdown(): void {
        document.getElementById('msDtTypeDropdown')?.classList.toggle('open');
    },

    async toggleDtTypeOption(el: HTMLInputElement): Promise<void> {
        try {
            const val = el.value as 'manual' | 'csv' | 'envoy';
            const newTypes = new Set(detailActiveTypes);
            if (el.checked) {
                newTypes.add(val);
            } else {
                newTypes.delete(val);
            }
            detailActiveTypes = newTypes;
            updateDtTypeBtnLabel();
            detailPage = 1;

            const { renderDetailRows } = await import('../pages/detail');
            renderDetailRows();
        } catch (err) {
            console.error('[DetailFilters] Error toggling type option:', err);
        }
    }
};
