/**
 * state.ts - Global dashboard state management.
 */

import type { WeekData } from './types/dashboard';
import type { Chart } from 'chart.js';

export type DashboardPage = 'overview' | 'trends' | 'detail' | 'calendar' | 'sla-email-tracker' | 'production';

/** Current active page */
export let currentPage: DashboardPage = 'overview';

/** Active data types (manual, csv, envoy) - global filter */
export let activeTypes = new Set<'manual' | 'csv' | 'envoy'>(['manual', 'csv', 'envoy']);

/** Current week index (0 = most recent) */
export let currentWeekIdx = 0;

/** Global reporting date range (YYYY-MM-DD). Defaults are initialized from data. */
export let dateRangeFrom: string = '';
export let dateRangeTo: string = '';

/** Filter: selected team member (or 'all') */
export let filterOwner: string = 'all';

/** Filter: selected country (or 'all') */
export let filterCountry: string = 'all';

/** Filter: selected document type (or 'all') */
export let filterDocType: string = 'all';

/** Chart instances registry */
export let charts: Record<string, Chart | undefined> = {};

/** LRU cache for decompressed week data */
export const WEEK_CACHE = new Map<string, WeekData>();

/** Cache for decompressed invoices data */
export let INVOICES_CACHE: any = null;

/** Dashboard data (loaded via global DASHBOARD_DATA) */
export const D = DASHBOARD_DATA;

// State setters
export function setCurrentPage(page: DashboardPage): void {
    currentPage = page;
}

export function setActiveTypes(types: Set<'manual' | 'csv' | 'envoy'>): void {
    activeTypes = types;
}

export function setCurrentWeekIdx(idx: number): void {
    currentWeekIdx = idx;
}

export function setDateRange(from: string, to: string): void {
    dateRangeFrom = from;
    dateRangeTo = to;
}

export function setDateRangeFrom(from: string): void {
    dateRangeFrom = from;
}

export function setDateRangeTo(to: string): void {
    dateRangeTo = to;
}

export function setFilterOwner(owner: string): void {
    filterOwner = owner;
}

export function setFilterCountry(country: string): void {
    filterCountry = country;
}

export function setFilterDocType(docType: string): void {
    filterDocType = docType;
}

export function setCharts(newCharts: Record<string, Chart | undefined>): void {
    charts = newCharts;
}

export function setInvoicesCache(data: any): void {
    INVOICES_CACHE = data;
}
