/**
 * Production Overrides page - aggregate productivity credit corrections.
 */

import { D } from '../state';
import type { ProductionOverrideEntry } from '../types/dashboard';

type WorkType = 'manual' | 'csv' | 'envoy';

type ProductionOverrideAdd = {
    date: string;
    from_member: string;
    to_member: string;
    count: number;
    work_type: WorkType;
    country?: string;
    company_code?: string;
    document_type?: string;
    reference?: string;
    reason?: string;
};

type ProductionPayload = {
    version: 1;
    app: 'invoice-process-dashboard';
    feature: 'production-credit-overrides';
    created_at: string;
    created_by: string;
    added: ProductionOverrideAdd[];
    deleted: Array<{ override_id: string }>;
};

type FileSystemPermissionMode = 'read' | 'readwrite';

type StoredDirectoryHandle = {
    kind: 'directory';
    requestPermission?: (descriptor?: { mode?: FileSystemPermissionMode }) => Promise<PermissionState>;
    queryPermission?: (descriptor?: { mode?: FileSystemPermissionMode }) => Promise<PermissionState>;
    getFileHandle: (name: string, options?: { create?: boolean }) => Promise<{
        createWritable: () => Promise<{
            write: (data: Blob) => Promise<void>;
            close: () => Promise<void>;
        }>;
    }>;
};

const WORK_TYPES: WorkType[] = ['envoy', 'manual', 'csv'];
const DB_NAME = 'invoice-production-overrides-store';
const STORE_NAME = 'handles';
const HANDLE_KEY = 'pending-dir';
const PICKER_ID = 'invoice-prod-pending';

let pendingHandle: StoredDirectoryHandle | null = null;

function el(id: string): HTMLElement | null {
    return document.getElementById(id);
}

function escapeHtml(value: string): string {
    return value.replace(/[&<>"']/g, char => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;',
    }[char] || char));
}

function todayIso(): string {
    return new Date().toISOString().slice(0, 10);
}

function sanitizeUser(value: string): string {
    return (value || 'teamleader').trim().replace(/[^A-Za-z0-9._-]+/g, '_') || 'teamleader';
}

function timestampForFilename(dateValue: Date): string {
    const pad = (n: number) => String(n).padStart(2, '0');
    return [
        dateValue.getFullYear(),
        pad(dateValue.getMonth() + 1),
        pad(dateValue.getDate()),
    ].join('-') + '-' + [
        pad(dateValue.getHours()),
        pad(dateValue.getMinutes()),
        pad(dateValue.getSeconds()),
    ].join('-');
}

function setStatus(message: string, tone: 'ok' | 'warn' | 'error' = 'ok'): void {
    const status = el('productionStatus');
    if (!status) return;
    status.textContent = message;
    status.className = `calendar-status ${tone}`;
}

function openDb(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);
        request.onupgradeneeded = () => {
            request.result.createObjectStore(STORE_NAME);
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
}

async function saveHandle(handle: StoredDirectoryHandle): Promise<void> {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        tx.objectStore(STORE_NAME).put(handle, HANDLE_KEY);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
    db.close();
}

async function loadHandle(): Promise<StoredDirectoryHandle | null> {
    const db = await openDb();
    const handle = await new Promise<StoredDirectoryHandle | null>((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const request = tx.objectStore(STORE_NAME).get(HANDLE_KEY);
        request.onsuccess = () => resolve((request.result as StoredDirectoryHandle | undefined) || null);
        request.onerror = () => reject(request.error);
    });
    db.close();
    return handle;
}

async function hasWritePermission(handle: StoredDirectoryHandle): Promise<boolean> {
    const descriptor = { mode: 'readwrite' as FileSystemPermissionMode };
    if (handle.queryPermission && await handle.queryPermission(descriptor) === 'granted') {
        return true;
    }
    if (handle.requestPermission) {
        return await handle.requestPermission(descriptor) === 'granted';
    }
    return false;
}

async function writeToDirectory(filename: string, payload: ProductionPayload): Promise<boolean> {
    if (!pendingHandle || !await hasWritePermission(pendingHandle)) {
        return false;
    }
    const fileHandle = await pendingHandle.getFileHandle(filename, { create: true });
    const writable = await fileHandle.createWritable();
    await writable.write(new Blob([JSON.stringify(payload, null, 2) + '\n'], { type: 'application/json' }));
    await writable.close();
    return true;
}

function downloadJson(filename: string, payload: ProductionPayload): void {
    const blob = new Blob([JSON.stringify(payload, null, 2) + '\n'], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
}

function buildPayload(
    added: ProductionPayload['added'],
    deleted: ProductionPayload['deleted'],
): { filename: string; payload: ProductionPayload } {
    const userInput = document.getElementById('productionUser') as HTMLInputElement | null;
    const user = sanitizeUser(userInput?.value || localStorage.getItem('invoiceProductionUser') || '');
    localStorage.setItem('invoiceProductionUser', user);
    const now = new Date();
    return {
        filename: `invoice_production_overrides_pending_${timestampForFilename(now)}_${user}.json`,
        payload: {
            version: 1,
            app: 'invoice-process-dashboard',
            feature: 'production-credit-overrides',
            created_at: now.toISOString(),
            created_by: user,
            added,
            deleted,
        },
    };
}

async function savePayload(payload: ProductionPayload, filename: string): Promise<void> {
    try {
        if (await writeToDirectory(filename, payload)) {
            setStatus(`Saved ${filename}`, 'ok');
            return;
        }
    } catch (err) {
        console.warn('[ProductionOverrides] Direct save failed, using download fallback.', err);
    }
    downloadJson(filename, payload);
    setStatus(`Downloaded ${filename}`, 'warn');
}

function sortedOverrides(): ProductionOverrideEntry[] {
    return [...(D.production_overrides || [])].sort((a, b) => (
        b.date.localeCompare(a.date) || a.from_member.localeCompare(b.from_member)
    ));
}

function optionList(values: string[], selected = ''): string {
    return values.map(value => (
        `<option value="${escapeHtml(value)}"${value === selected ? ' selected' : ''}>${escapeHtml(value)}</option>`
    )).join('');
}

function renderTableRows(overrides: ProductionOverrideEntry[]): string {
    if (!overrides.length) {
        return '<tr><td colspan="10" class="calendar-empty">No production overrides found</td></tr>';
    }
    return overrides.map(row => `
        <tr>
          <td>${escapeHtml(row.date)}</td>
          <td>${escapeHtml(row.from_member)}</td>
          <td>${escapeHtml(row.to_member)}</td>
          <td>${row.count}</td>
          <td><span class="calendar-type">${escapeHtml(row.work_type.toUpperCase())}</span></td>
          <td>${escapeHtml(row.country || '')}</td>
          <td>${escapeHtml(row.company_code || '')}</td>
          <td>${escapeHtml(row.document_type || '')}</td>
          <td>${escapeHtml(row.reference || row.reason || '')}</td>
          <td>
            <button class="calendar-icon-btn" title="Delete override" onclick="deleteProductionOverride('${escapeHtml(row.override_id)}')">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/></svg>
            </button>
          </td>
        </tr>
    `).join('');
}

export async function renderProductionOverrides(): Promise<void> {
    const page = el('pageProduction');
    if (!page) return;

    const savedUser = localStorage.getItem('invoiceProductionUser') || 'teamleader';
    const overrides = sortedOverrides();
    const defaultFrom = D.team_members[0] || '';
    const defaultTo = D.team_members.find(member => member !== defaultFrom) || '';
    const docTypes = ['', ...(D.all_doc_types || [])];
    page.innerHTML = `
      <div class="page-header">
        <div>
          <h1 class="page-title">Production Overrides</h1>
          <p class="page-subtitle">Aggregate credit corrections for current or historical weeks</p>
        </div>
        <button class="calendar-connect-btn" onclick="connectProductionOverridesFolder()">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20h16"/><path d="M12 4v12"/><path d="m6 10 6 6 6-6"/></svg>
          Connect Folder
        </button>
      </div>

      <div class="calendar-grid">
        <section class="calendar-panel">
          <div class="section-title">Add Override</div>
          <div class="calendar-form">
            <label>Date<input id="productionDate" type="date" value="${todayIso()}"></label>
            <label>From<select id="productionFromMember">${optionList(D.team_members, defaultFrom)}</select></label>
            <label>To<select id="productionToMember">${optionList(D.team_members, defaultTo)}</select></label>
            <label>Count<input id="productionCount" type="number" min="1" step="1" value="1"></label>
            <label>Type<select id="productionWorkType">${WORK_TYPES.map(t => `<option value="${t}">${t.toUpperCase()}</option>`).join('')}</select></label>
            <label>Company Code<input id="productionCompanyCode" type="text" maxlength="8"></label>
            <label>Doc Type<select id="productionDocumentType">${optionList(docTypes)}</select></label>
            <label>Reference<input id="productionReference" type="text"></label>
            <label>Reason<input id="productionReason" type="text"></label>
            <label>Saved By<input id="productionUser" type="text" value="${escapeHtml(savedUser)}"></label>
            <button class="calendar-save-btn" onclick="saveProductionOverride()">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8"/><path d="M7 3v5h8"/></svg>
              Save
            </button>
          </div>
          <div id="productionStatus" class="calendar-status">Ready</div>
        </section>

        <section class="calendar-panel">
          <div class="section-title">Current Overrides</div>
          <div class="calendar-table-wrap">
            <table class="calendar-table">
              <thead><tr><th>Date</th><th>From</th><th>To</th><th>Count</th><th>Type</th><th>Country</th><th>Co Code</th><th>Doc</th><th>Note</th><th></th></tr></thead>
              <tbody>${renderTableRows(overrides)}</tbody>
            </table>
          </div>
        </section>
      </div>
    `;

    try {
        pendingHandle = await loadHandle();
        if (pendingHandle) {
            setStatus('Folder connected', 'ok');
        }
    } catch (err) {
        console.warn('[ProductionOverrides] Stored folder handle unavailable.', err);
    }
}

async function connectProductionOverridesFolder(): Promise<void> {
    const picker = (window as unknown as {
        showDirectoryPicker?: (options?: { id?: string; mode?: FileSystemPermissionMode; startIn?: string }) => Promise<StoredDirectoryHandle>;
    }).showDirectoryPicker;
    if (!picker) {
        setStatus('Direct folder save is not available in this browser', 'warn');
        return;
    }
    try {
        pendingHandle = await picker({
            id: PICKER_ID,
            mode: 'readwrite',
            startIn: 'documents',
        });
        await saveHandle(pendingHandle);
        setStatus('Folder connected', 'ok');
    } catch (err) {
        console.warn('[ProductionOverrides] Folder connection cancelled or failed.', err);
        setStatus('Folder not connected', 'warn');
    }
}

async function saveProductionOverride(): Promise<void> {
    const date = (document.getElementById('productionDate') as HTMLInputElement | null)?.value || '';
    const fromMember = (document.getElementById('productionFromMember') as HTMLSelectElement | null)?.value || '';
    const toMember = (document.getElementById('productionToMember') as HTMLSelectElement | null)?.value || '';
    const count = Number((document.getElementById('productionCount') as HTMLInputElement | null)?.value || 0);
    const workType = (document.getElementById('productionWorkType') as HTMLSelectElement | null)?.value as WorkType;
    const companyCode = ((document.getElementById('productionCompanyCode') as HTMLInputElement | null)?.value || '').trim().toUpperCase();
    const documentType = ((document.getElementById('productionDocumentType') as HTMLSelectElement | null)?.value || '').trim().toUpperCase();
    const reference = ((document.getElementById('productionReference') as HTMLInputElement | null)?.value || '').trim();
    const reason = ((document.getElementById('productionReason') as HTMLInputElement | null)?.value || '').trim();

    if (!date || !fromMember || !toMember || fromMember === toMember || !Number.isInteger(count) || count <= 0 || !WORK_TYPES.includes(workType)) {
        setStatus('Check date, members, count and type', 'error');
        return;
    }

    const { filename, payload } = buildPayload([{
        date,
        from_member: fromMember,
        to_member: toMember,
        count,
        work_type: workType,
        company_code: companyCode,
        document_type: documentType,
        reference,
        reason,
    }], []);
    await savePayload(payload, filename);
}

async function deleteProductionOverride(overrideId: string): Promise<void> {
    const { filename, payload } = buildPayload([], [{ override_id: overrideId }]);
    await savePayload(payload, filename);
}

export const productionOverridesWindowBindings = {
    connectProductionOverridesFolder,
    saveProductionOverride,
    deleteProductionOverride,
};
