/**
 * overview-charts.ts - Chart rendering for Overview page (weekly bar + doc type doughnut).
 */

import { D, charts } from '../state';
import { fmt, pct } from '../utils/formatters';
import { RGBA_COLORS, RGBA_COLORS_FULL, DOC_TYPE_COLORS } from '../config';
import { Chart } from 'chart.js';
import type { FilteredMemberDay } from '../types/filtered';

/** Data shape for overview charts */
interface OverviewChartData {
    members: string[];
    totals: Record<string, FilteredMemberDay>;
    workingDays: number;
    weekTarget: number;
    workingDaysPerMember?: Record<string, number>;
}

/**
 * Render horizontal bar chart showing weekly totals per member.
 * Includes target line and per-member average/day labels.
 *
 * @param f - Filtered week data for chart
 */
export function renderWeeklyChart(f: OverviewChartData): void {
    const canvas = document.getElementById('cWeekly') as HTMLCanvasElement | null;
    if (!canvas) return;

    const isLight = document.body.classList.contains('light');
    const lblColor = isLight ? '#1e293b' : '#e8ecf4';

    // Sort members by total (descending)
    const sorted = f.members.map(m => {
        const ci = D.team_members.indexOf(m);
        const md = f.workingDaysPerMember?.[m] ?? (f.workingDays || 5);
        return {
            name: m,
            total: f.totals[m].total,
            bg: RGBA_COLORS[ci % RGBA_COLORS.length],
            border: RGBA_COLORS_FULL[ci % RGBA_COLORS_FULL.length],
            avgDay: (f.totals[m].total / md).toFixed(1)
        };
    }).sort((a, b) => b.total - a.total);

    charts.weekly = new Chart(canvas, {
        type: 'bar',
        data: {
            labels: sorted.map(d => d.name),
            datasets: [{
                label: 'Invoices',
                data: sorted.map(d => d.total),
                backgroundColor: sorted.map(d => d.bg),
                borderColor: sorted.map(d => d.border),
                borderWidth: 2,
                barThickness: 32,
            }]
        },
        options: {
            indexAxis: 'y',
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { top: 24, right: 120 } },
            plugins: {
                legend: { display: false },
                tooltip: {
                    backgroundColor: '#1a2340',
                    padding: 12,
                    cornerRadius: 8,
                    titleFont: { family: "'DM Sans'", size: 13, weight: '600' },
                    bodyFont: { family: "'JetBrains Mono'", size: 12 },
                    callbacks: {
                        label: (c: { raw: unknown }) => `  Total: ${fmt(c.raw as number)} invoices`,
                        afterLabel: (c: { dataIndex: number }) => `  Avg/day: ${sorted[c.dataIndex].avgDay}`
                    }
                }
            },
            scales: {
                x: {
                    beginAtZero: true,
                    ticks: { font: { family: "'JetBrains Mono'", size: 10 } },
                    grid: { color: isLight ? 'rgba(0,0,0,.06)' : 'rgba(255,255,255,.04)' }
                },
                y: {
                    grid: { display: false },
                    ticks: {
                        font: { family: "'DM Sans'", weight: '600', size: 13 },
                        color: lblColor
                    }
                }
            },
            animation: { duration: 500, easing: 'easeOutQuart' }
        },
        plugins: [
            {
                id: 'barLabels',
                afterDatasetsDraw(chart: Chart) {
                    const ctx = chart.ctx;
                    const meta = chart.getDatasetMeta(0);
                    meta.data.forEach((bar: { x: number; y: number }, i: number) => {
                        const val = chart.data.datasets[0].data[i] as number;
                        const avg = sorted[i].avgDay;
                        ctx.save();
                        ctx.fillStyle = lblColor;
                        ctx.font = "700 13px 'JetBrains Mono'";
                        ctx.textAlign = 'left';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(`${fmt(val)}  (${avg}/d)`, bar.x + 10, bar.y);
                        ctx.restore();
                    });
                }
            },
            {
                id: 'targetLine',
                afterDraw(chart: Chart) {
                    const xS = chart.scales.x;
                    const tx = xS.getPixelForValue(f.weekTarget);
                    if (tx < xS.left || tx > xS.right) return;

                    const ctx = chart.ctx;
                    ctx.save();
                    ctx.beginPath();
                    ctx.setLineDash([5, 4]);
                    ctx.strokeStyle = '#ef4444';
                    ctx.lineWidth = 1.5;
                    ctx.moveTo(tx, chart.chartArea.top);
                    ctx.lineTo(tx, chart.chartArea.bottom);
                    ctx.stroke();

                    ctx.fillStyle = '#ef4444';
                    ctx.font = "600 10px 'JetBrains Mono'";
                    ctx.textAlign = 'center';
                    ctx.fillText(`Target: ${f.weekTarget}`, tx, chart.chartArea.top - 8);
                    ctx.restore();
                }
            }
        ]
    });
}

/**
 * Render doughnut chart showing document type distribution.
 * @param f - Filtered week data for chart
 */
export function renderDocTypeChart(f: OverviewChartData): void {
    const ctx = document.getElementById('cDocType') as HTMLCanvasElement | null;
    if (!ctx) return;

    // Aggregate document types across all members
    const docC: Record<string, number> = {};
    f.members.forEach(m => {
        Object.entries(f.totals[m].by_doc_type || {}).forEach(([dt, c]) => {
            docC[dt] = (docC[dt] || 0) + c;
        });
    });

    const sorted = Object.entries(docC).sort((a, b) => b[1] - a[1]);
    if (!sorted.length) return;

    charts.docType = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: sorted.map(([dt]) => D.doc_type_labels[dt] || dt),
            datasets: [{
                data: sorted.map(([, c]) => c),
                backgroundColor: DOC_TYPE_COLORS.slice(0, sorted.length),
                borderWidth: 0,
                hoverOffset: 5
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '64%',
            plugins: {
                legend: {
                    position: 'bottom',
                    labels: { font: { size: 11 }, padding: 10 }
                },
                tooltip: {
                    backgroundColor: '#1a2340',
                    bodyFont: { family: "'JetBrains Mono'", size: 12 },
                    callbacks: {
                        label: (c: { dataset: { data: number[] }; label: string; raw: unknown }) => {
                            const t = (c.dataset.data as number[]).reduce((s: number, v: number) => s + v, 0);
                            return `  ${c.label}: ${fmt(c.raw as number)} (${pct(c.raw as number, t)}%)`;
                        }
                    }
                }
            },
            animation: { animateRotate: true, duration: 600 }
        },
        plugins: [{
            id: 'center',
            afterDraw(chart: Chart) {
                const t = (chart.data.datasets[0].data as number[]).reduce((s, v) => s + v, 0);
                const { width, height, top, left } = chart.chartArea;
                const ctx = chart.ctx;

                // Read theme-aware colors from CSS variables
                const styles = getComputedStyle(document.body);
                const textColor = styles.getPropertyValue('--text').trim() || '#e8ecf4';
                const mutedColor = styles.getPropertyValue('--text-muted').trim() || '#5a6a8a';

                ctx.save();
                ctx.font = "700 1.2rem 'JetBrains Mono'";
                ctx.fillStyle = textColor;  // Theme-aware: --text variable
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(fmt(t), left + width / 2, top + height / 2 - 7);
                ctx.font = "400 .6rem 'DM Sans'";
                ctx.fillStyle = mutedColor;  // Theme-aware: --text-muted variable
                ctx.fillText('total', left + width / 2, top + height / 2 + 11);
                ctx.restore();
            }
        }]
    });
}
